INSERT INTO public."applications" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id") SELECT "slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "id" FROM jsonb_populate_recordset(null::public."applications", '[{"id": 1, "name": {"en-us": "Basic research", "pt-br": "Pesquisa básica"}, "slug": "basic-research", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 1, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Research conducted primarily to increase fundamental knowledge of biological, chemical or other phenomena, without an immediate practical or regulatory objective.", "pt-br": "Pesquisa realizada principalmente para ampliar o conhecimento fundamental sobre fenômenos biológicos, químicos ou outros, sem objetivo prático ou regulatório imediato."}}, {"id": 2, "name": {"en-us": "Translational and applied research", "pt-br": "Pesquisa translacional e aplicada"}, "slug": "translational-applied-research", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 2, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Research intended to apply or translate scientific knowledge toward a defined practical objective, including the prevention, diagnosis or treatment of disease and the improvement of human, animal or plant health and welfare.", "pt-br": "Pesquisa destinada a aplicar ou traduzir conhecimento científico para um objetivo prático definido, incluindo prevenção, diagnóstico ou tratamento de doenças e melhoria da saúde e do bem-estar humano, animal ou vegetal."}}, {"id": 3, "name": {"en-us": "Regulatory use", "pt-br": "Uso regulatório"}, "slug": "regulatory-use", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 3, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Use intended to generate information required, recommended or accepted by legislation or a regulatory authority for assessing the quality, safety, efficacy or environmental effects of a substance, product or intervention.", "pt-br": "Uso destinado a gerar informações exigidas, recomendadas ou aceitas pela legislação ou por uma autoridade regulatória para avaliar a qualidade, segurança, eficácia ou os efeitos ambientais de uma substância, produto ou intervenção."}}, {"id": 4, "name": {"en-us": "Routine production", "pt-br": "Produção de rotina"}, "slug": "routine-production", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 4, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Routine use associated with manufacturing, product consistency, quality control, potency testing or batch release, rather than research or initial method development.", "pt-br": "Uso rotineiro associado à fabricação, consistência do produto, controle de qualidade, ensaio de potência ou liberação de lotes, em vez de pesquisa ou desenvolvimento inicial de métodos."}}, {"id": 5, "name": {"en-us": "Education and training", "pt-br": "Ensino e treinamento"}, "slug": "education-training", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 5, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Use for teaching, demonstration or the acquisition, maintenance, improvement or assessment of academic, practical or professional knowledge and skills.", "pt-br": "Uso para ensino, demonstração ou aquisição, manutenção, aperfeiçoamento ou avaliação de conhecimentos e competências acadêmicas, práticas ou profissionais."}}, {"id": 6, "name": {"en-us": "Protection of the natural environment", "pt-br": "Proteção do meio ambiente natural"}, "slug": "environmental-protection", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 6, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Use primarily intended to protect the natural environment in the interests of the health or welfare of humans, animals or ecological systems.", "pt-br": "Uso destinado principalmente a proteger o meio ambiente natural em benefício da saúde ou do bem-estar de seres humanos, animais ou sistemas ecológicos."}}, {"id": 7, "name": {"en-us": "Preservation of species", "pt-br": "Preservação de espécies"}, "slug": "species-preservation", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 7, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Research or other use primarily intended to support the conservation, recovery or continued survival of a species or population.", "pt-br": "Pesquisa ou outro uso destinado principalmente a apoiar a conservação, recuperação ou sobrevivência continuada de uma espécie ou população."}}, {"id": 8, "name": {"en-us": "Forensic inquiry", "pt-br": "Investigação forense"}, "slug": "forensic-inquiry", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 8, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Use in an investigation conducted primarily for legal, judicial, criminalistic or other forensic purposes.", "pt-br": "Uso em investigação realizada principalmente para fins legais, judiciais, criminalísticos ou outros fins forenses."}}, {"id": 9, "name": {"en-us": "Other", "pt-br": "Outro"}, "slug": "other", "active": true, "created_at": "2026-08-15T12:46:04.109395+00:00", "sort_order": 9, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "A known purpose that is not represented by another value in this controlled vocabulary.", "pt-br": "Uma finalidade conhecida que não é representada por outro valor deste vocabulário controlado."}}, {"id": 10, "name": {"en-us": "Diagnostic testing", "pt-br": "Teste diagnóstico"}, "slug": "diagnostic-testing", "active": true, "created_at": "2026-10-09T16:53:09.48887+00:00", "sort_order": 10, "updated_at": "2026-10-09T16:53:09.48887+00:00