INSERT INTO public."documents" ("id", "slug", "doc_citation", "description", "date", "categories", "institution", "url") SELECT "id", "slug", "doc_citation", "description", "date", "categories", "institution", "url" FROM jsonb_populate_recordset(null::public."documents", '[{"id": 5, "url": "https://www.in.gov.br/web/dou/-/resolucao-n-56-de-5-de-outubro-de-2022-434544861", "date": "2022-10-05", "slug": "concea-rn-56-2022-10-05", "categories": ["regulation"], "description": {"en-us": "Official normative resolution recognizing and standardizing the use of validated alternative methods to animal use in research activities in Brazil, including OECD test guidelines for human health and biotic systems.", "pt-br": "Resolução normativa que reconhece e oficializa o uso de métodos alternativos validados ao uso de animais em atividades de pesquisa no Brasil, incluindo diretrizes de ensaio da OCDE para saúde humana e efeitos em sistemas bióticos."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2022), Normative Resolution No. 56, October 5, 2022, Diário Oficial da União, Brazil.", "pt-br": "CONCEA (2022), Resolução Normativa nº 56, de 5 de outubro de 2022, Diário Oficial da União, Brasília."}}, {"id": 8, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-75_2026-reconhece-metodo-alternativo-diagnostico-de-raiva-animal_dou-23-01-2026.pdf", "date": "2026-01-22", "slug": "concea-rn-75-2026-01-22", "categories": ["regulation"], "description": {"en-us": "Recognizes alternative methods to the use of animals for rabies diagnosis, including DFA, dRIT, RT-PCR/RT-qPCR, and RTCIT. Establishes a five-year deadline for the mandatory replacement of the mouse inoculation test (MIT).", "pt-br": "Reconhece métodos alternativos ao uso de animais para o diagnóstico da raiva, incluindo DFA, dRIT, RT-PCR/RT-qPCR e RTCIT. Estabelece o prazo de cinco anos para a substituição obrigatória do teste de inoculação em camundongos (MIT)."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2026), Normative Resolution No. 75, January 22, 2026, Diário Oficial da União, Edição 16, Seção 1, Página 8, Brasília.", "pt-br": "CONCEA (2026), Resolução Normativa CONCEA nº 75, de 22 de janeiro de 2026, Diário Oficial da União, Edição 16, Seção 1, Página 8, Brasília."}}, {"id": 12, "url": "https://doi.org/10.1787/9789264070943-en", "date": "2002-02-08", "slug": "oecd-test-no-420-2002-02-08-acute-oral-toxicity-fixed-dose-procedure", "categories": ["method_protocol", "regulation"], "description": {"en-us": "The Fixed Dose Procedure is an acute oral toxicity test in which doses expected to be lethal are avoided. It uses a stepwise procedure to identify the dose causing evident toxicity or death, providing information for hazard classification according to the GHS.", "pt-br": "O Procedimento de Dose Fixa é um teste de toxicidade aguda oral no qual doses esperadas como letais são evitadas. Utiliza um procedimento gradual para identificar a dose que causa toxicidade evidente ou morte, fornecendo informações para a classificação de perigo conforme o GHS."}, "institution": {"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}, "doc_citation": {"en-us": "OECD (2002), Test No. 420: Acute Oral Toxicity - Fixed Dose Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264070943-en.", "pt-br": "OECD (2002), Test No. 420: Acute Oral Toxicity - Fixed Dose Procedure, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264070943-en."}}, {"id": 6, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-77_2026-reconhece-metodo-alternativo_fator-c.pdf", "date": "2026-07-22", "slug": "concea-rn-77-2026-07-22", "categories": ["regulation"], "description": {"en-us": "This resolution formally recognizes the recombinant Factor C (rFC) method as an alternative to animal-based Limulus Amebocyte Lysate (LAL) testing for the detection of bacterial endotoxins, setting a five-year deadline for the mandatory transition.", "pt-br": "Esta resolução reconhece formalmente o método do Fator C recombinante (rFC) como alternativa ao uso do Lisado de Amebócitos de Limulus (LAL) para detecção de endotoxinas bacterianas, estabelecendo um prazo de cinco anos para a substituição obrigatória."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2026), Normative Resolution No. 77, July 22, 2026.", "pt-br": "CONCEA (2026), Resolução Normativa CONCEA nº 77, de 22 de julho de 2026, Reconhece método alternativo ao uso de animais para a detecção de endotoxinas bacterianas."}}, {"id": 2, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-45-de-22-de-outubro-de-2019.pdf", "date": "2019-10-22", "slug": "concea-rn-45-2019-10-22", "categories": ["regulation"], "description": {"en-us": "Recognizes the Monocyte Activation Test as an alternative method for evaluating pyrogenic contamination in injectable products, as part of the strategy to reduce, replace, or refine animal use in research.", "pt-br": "Reconhece o Teste de Ativação de Monócitos como método alternativo para avaliação de contaminação pirogênica em produtos injetáveis, visando a redução, substituição ou refinamento do uso de animais em pesquisa."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2019), Normative Resolution No. 45, October 22, 2019", "pt-br": "CONCEA (2019), Resolução Normativa nº 45, de 22 de outubro de 2019"}}, {"id": 7, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-concea-no-76-de-6-de-fevereiro-de-2026-resolucao-concea-no-76-de-6-de-fevereiro-de-2026-dou-imprensa-nacional.pdf", "date": "2026-02-06", "slug": "concea-rn-76-2026-02-06", "categories": ["regulation"], "description": {"en-us": "Resolution recognizing the OECD TG 492B method (Reconstructed Human Cornea-like Epithelium) for eye hazard identification in Brazil, establishing a five-year deadline for the replacement of animal-based methods.", "pt-br": "Resolução que reconhece o método OECD TG 492B (Epitélio semelhante à córnea humana) para avaliação de irritação e corrosão ocular no Brasil, estabelecendo prazo de cinco anos para a substituição de métodos que utilizam animais."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2026), Normative Resolution No. 76, February 6, 2026.", "pt-br": "CONCEA (2026), Resolução Normativa No. 76, de 6 de fevereiro, 2026."}}, {"id": 1, "url": "https://bibliotecadigital.anvisa.gov.br/jspui/handle/anvisa/11937", "date": "2024-11-01", "slug": "farmacopeia-brasileira-7-I", "categories": ["method_protocol"], "description": {"en-us": "The 7th edition of the Brazilian Pharmacopoeia (Anvisa, 2024) sets quality standards for pharmaceuticals in Brazil. Key highlights include the Monocyte Activation Test (replacing animal testing), international harmonization, 12 new texts, revisions, and consolidated updates.", "pt-br": "A 7ª edição da Farmacopeia Brasileira (Anvisa, 2024) estabelece padrões de qualidade farmacêutica no Brasil. Destaques incluem o Teste de Ativação de Monócitos (alternativo ao uso de animais), harmonização internacional, 12 novos textos, revisões técnicas e consolidação da 6ª edição."}, "institution": {"en-us": "Agência Nacional de Vigilância Sanitária (Anvisa), Brazil", "pt-br": "Agência Nacional de Vigilância Sanitária (Anvisa), Brasil"}, "doc_citation": {"en-us": "Farmacopeia Brasileira, 7ª edition: volume I - RDC version no 940/2024", "pt-br": "Farmacopeia Brasileira, 7ª edição: volume I - versão RDC nº 940/2024"}}, {"id": 11, "url": "https://doi.org/10.1787/d77a7e39-en", "date": "2010-07-20", "slug": "oecd-gd-no-129-2010-07-20-guidance-document-on-using-cytotoxicity-tests-to-estimate-starting-doses-for-acu", "categories": ["method_protocol", "guideline", "regulation"], "description": {"en-us": "This guidance document details the use of in vitro basal cytotoxicity assays (using 3T3 or NHK cells) to predict LD50 values for the purpose of estimating starting doses for acute oral systemic toxicity tests, aiming to refine and reduce animal use.", "pt-br": "Este documento de orientação detalha o uso de ensaios de citotoxicidade basal in vitro (usando células 3T3 ou NHK) para prever valores de DL50 com o objetivo de estimar doses iniciais para testes de toxicidade sistêmica oral aguda, visando refinar e reduzir o uso de animais."}, "institution": {"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}, "doc_citation": {"en-us": "OECD (2010), Guidance Document on Using Cytotoxicity Tests to Estimate Starting Doses for Acute Oral Systematic Toxicity Tests, OECD Series on Testing and Assessment, No. 129, OECD Publishing, Paris, https://doi.org/10.1787/d77a7e39-en.", "pt-br": "OECD (2010), Guidance Document on Using Cytotoxicity Tests to Estimate Starting Doses for Acute Oral Systematic Toxicity Tests, OECD Series on Testing and Assessment, No. 129, OECD Publishing, Paris, https://doi.org/10.1787/d77a7e39-en."}}, {"id": 13, "url": "https://doi.org/10.1787/9789264071001-en", "date": "2002-02-08", "slug": "oecd-test-no-423-2002-02-08-acute-oral-toxicity-acute-toxic-class-method", "categories": ["method_protocol", "regulation"], "description": {"en-us": "The acute toxic class method is a stepwise procedure using a minimum number of animals to rank substances according to their acute oral toxicity by classifying them into one of several toxicity classes based on fixed LD50 cut-off values.", "pt-br": "The acute toxic class method is a stepwise procedure using a minimum number of animals to rank substances according to their acute oral toxicity by classifying them into one of several toxicity classes based on fixed LD50 cut-off values."}, "institution": {"en-us": "Organisation for Economic Co-operation and Development (OECD)", "pt-br": "Organização para a Cooperação e Desenvolvimento Econômico (OCDE)"}, "doc_citation": {"en-us": "OECD (2002), Test No. 423: Acute Oral toxicity - Acute Toxic Class Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071001-en.", "pt-br": "OECD (2002), Test No. 423: Acute Oral toxicity - Acute Toxic Class Method, OECD Guidelines for the Testing of Chemicals, Section 4, OECD Publishing, Paris, https://doi.org/10.1787/9789264071001-en."}}, {"id": 4, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-18-de-24-de-setembro-de-2014.pdf", "date": "2014-09-24", "slug": "concea-rn-18-2014-09-24", "categories": ["regulation"], "description": {"en-us": "This normative resolution recognizes 17 alternative methods to the use of animals in research activities in Brazil, establishing a five-year deadline for the mandatory replacement of original methods with these validated alternatives.", "pt-br": "Esta resolução normativa reconhece 17 métodos alternativos ao uso de animais em atividades de pesquisa no Brasil, estabelecendo o prazo de até cinco anos para a substituição obrigatória dos métodos originais por estes métodos alternativos validados."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2014), Normative Resolution No. 18, September 24, 2014.", "pt-br": "CONCEA (2014), Resolução Normativa nº 18, de 24 de setembro de 2014."}}, {"id": 3, "url": "https://www.gov.br/mcti/pt-br/composicao/colegiados/concea/arquivos/arquivo/legislacao/resolucao-normativa-no-31-de-18-de-agosto-de-2016.pdf", "date": "2016-08-18", "slug": "concea-rn-31-2016-08-18", "categories": ["regulation"], "description": {"en-us": "Brazilian normative resolution that recognizes seven internationally validated alternative methods for ocular irritation/corrosion, skin sensitization, reproductive toxicity, and pyrogenic contamination to reduce, replace, or refine animal use in research.", "pt-br": "Resolução normativa brasileira que reconhece sete métodos alternativos validados internacionalmente para irritação/corrosão ocular, sensibilização cutânea, toxicidade reprodutiva e contaminação pirogênica visando a redução, substituição ou refinamento do uso de animais em pesquisa."}, "institution": {"en-us": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brazil", "pt-br": "Conselho Nacional de Controle de Experimentação Animal (CONCEA), Brasil"}, "doc_citation": {"en-us": "CONCEA (2016), Normative Resolution No. 31, August 18, 2016.", "pt-br": "CONCEA (2016), Resolução Normativa nº 31, de 18 de agosto de 2016, Reconhece métodos alternativos ao uso de animais em atividades de pesquisa no Brasil, Conselho Nacional de Controle de Experimentação Animal, Brasília."}}, {"id": 49, "url