ernal_oht_codes": []}, {"id": 57, "code": "6.1.4", "name": {"en-us": "Infectious virus isolation", "pt-br": "Isolamento de vírus infeccioso"}, "slug": "infectious-virus-isolation", "active": true, "parent_id": 53, "created_at": "2026-10-09T20:18:54.818308+00:00", "sort_order": 57, "updated_at": "2026-10-09T21:08:33.623998+00:00", "description": {"en-us": "Demonstration of virus capable of infection and replication in a permissive system.", "pt-br": "Demonstração da presença de vírus capaz de infectar e se replicar em um sistema permissivo."}, "external_oht_codes": []}, {"id": 55, "code": "6.1.2", "name": {"en-us": "Viral antigen detection", "pt-br": "Detecção de antígeno viral"}, "slug": "viral-antigen-detection", "active": true, "parent_id": 53, "created_at": "2026-10-09T20:15:14.349827+00:00", "sort_order": 55, "updated_at": "2026-10-09T21:08:22.977596+00:00", "description": {"en-us": "Identification of viral antigens in a sample.", "pt-br": "Identificação da presença de antígenos virais em uma amostra."}, "external_oht_codes": []}, {"id": 58, "code": "3.3", "name": {"en-us": "Basal cytotoxicity", "pt-br": "Citotoxicidade basal"}, "slug": "basal-cytotoxicity", "active": true, "parent_id": 31, "created_at": "2026-10-09T22:01:20.762879+00:00", "sort_order": 58, "updated_at": "2026-10-09T22:01:20.762879+00:00", "description": {"en-us": "Non-specific reduction in the viability of cultured cells following exposure to a test substance.", "pt-br": "Redução inespecífica da viabilidade de células cultivadas após exposição a uma substância de teste."}, "external_oht_codes": ["201"]}]'::jsonb);
INSERT INTO public."feedback" ("id", "user_id", "url", "object", "feedback_text", "created_at") SELECT "id", "user_id", "url", "object", "feedback_text", "created_at" FROM jsonb_populate_recordset(null::public."feedback", '[{"id": 1, "url": "http://localhost:5173/explore/methods", "object": "Test Method", "user_id": null, "created_at": "2026-08-11T19:20:29.334444+00:00", "feedback_text": "hello"}, {"id": 2, "url": "http://localhost:5173/explore/methods", "object": "Acute Oral Toxicity – Acute Toxic Class Method", "user_id": null, "created_at": "2026-08-11T19:25:02.885274+00:00", "feedback_text": "teste"}, {"id": 3, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda", "user_id": null, "created_at": "2026-08-14T18:28:06.602697+00:00", "feedback_text": "Justificativa da redução em ingles"}, {"id": 4, "url": "https://3r-assist.vercel.app/explore", "object": "Bacterial Endotoxins Test (LAL)", "user_id": null, "created_at": "2026-09-04T18:36:09.42301+00:00", "feedback_text": "teste"}, {"id": 5, "url": "https://3r-assist.vercel.app/explore", "object": "Direct rapid immunohistochemistry test (dRIT) for rabies diagnosis", "user_id": null, "created_at": "2026-09-08T20:53:34.885892+00:00", "feedback_text": "O título e a descrição estão em inglês. Acho que deveria ser em português, né?\nConsideramos que o título em portugues deve ficar exatamente igual está na RN do CONCEA, que está assim: Teste Rápido de Imuno-histoquímica Direta (Direct Rapid Immunohistochemistry Test) - dRIT;\n\nO \"\"uso de animais\" está errado porque não é de abatedouro. Mas se for relacionado a informar se o teste usa animais ou derivados poderia informar \"potencial uso de insumos de origem animal\". \nO \"sistema de teste\" está \"ex vivo\" e deveria ser  \"in vitro\". \nEm categoria de desfecho, deveria estar: diagnóstico da raiva animal\nAplicação está \"pesquisa básica\", deveria ser: \"teste diagnóstico\""}, {"id": 6, "url": "https://3r-assist.vercel.app/explore", "object": "Direct rapid immunohistochemistry test (dRIT) for rabies diagnosis", "user_id": null, "created_at": "2026-09-08T21:17:45.570828+00:00", "feedback_text": "O status de validação correto seria: Reconhecido. \n\nIsso considerando essa hierarquia de satatus que propomos:\n\nAs categorias de status devem ser: \n-Validado (que tem aceitação regulatória internacional, ex; métodos que estão na OECD, farmacopeia ou que estejam descritos e recomendados por organizações de referência internacional como a OMS)\n- Reconhecido (essa categoria é específica da nossa regulamentação do Brasil)\n- Em processo de validação (já está em processo pelos centros de validação mas ainda não consta nos catálogos)\n-  Descrito na Literatura científica - Descrito/publicado na literatura científica \n- Descrito na Literatura cinzenta (descrito em pôster, anais de congresso, essas coisas)"}, {"id": 7, "url": "https://3r-assist.vercel.app/explore", "object": "Ensaio do Linfonodo Local (LLNA)", "user_id": null, "created_at": "2026-09-08T21:25:11.740627+00:00", "feedback_text": "O Título está errado, o correto (para ficar igual a RN) seria: Método OECD TG 429 - Sensibilização Cutânea:\nEnsaio do Linfonodo Local;"}, {"id": 8, "url": "https://3r-assist.vercel.app/explore", "object": "Ensaio de Opacidade e Permeabilidade da Córnea Bovina (BCOP)", "user_id": null, "created_at": "2026-09-08T21:31:58.17918+00:00", "feedback_text": "Para ficar com o título igual da RN deve ser:\nMétodo OECD TG 437 - Teste de Permeabilidade e Opacidade de Córnea Bovina;\nNa descrição deve trocar \"um método de teste in vitro\" por \"um métodos de teste ex vivo\"\nNa categoria, deve ficar \"irritação e corrosão ocular\""}, {"id": 9, "url": "https://3r-assist.vercel.app/explore", "object": "Método de Teste de Olho de Frango Isolado", "user_id": null, "created_at": "2026-09-08T21:39:19.051712+00:00", "feedback_text": "No título deve estar: Método OECD TG 438 - Teste de Olho Isolado de Galinha;\nNa descrição, trocar \"um método de teste in vitro\" por \"um método de teste ex vivo\".\nNa categoria deve estar \"irritação e corrosão ocular\".\n\nIncluir como referêncioa a RN 18 do CONCEA."}, {"id": 10, "url": "https://3r-assist.vercel.app/explore", "object": "Método de Teste de Olho de Frango Isolado", "user_id": null, "created_at": "2026-09-08T21:41:12.767949+00:00", "feedback_text": "O status regulatório é \"reconhecido no Brasil\""}, {"id": 11, "url": "https://3r-assist.vercel.app/explore", "object": "Test No. 442C: Sensibilização Cutânea In Chemico", "user_id": null, "created_at": "2026-09-08T21:44:21.572756+00:00", "feedback_text": "O Título deve ficar: Método OECD TG 442C - Sensibilização cutânea in chemico;\n\nNa descrição, trocar: \"evento iniciador molecular\" para \"evento molecular inicial\".\nStatus de validação é Reconhecido no Brasil\n\nIncluir RN 32 do CONCEA na referência"}, {"id": 12, "url": "https://3r-assist.vercel.app/explore", "object": "Ensaios de RT-PCR para Diagnóstico de Raiva", "user_id": null, "created_at": "2026-09-09T00:58:08.221275+00:00", "feedback_text": "No título, substituir \"Ensaios de RT-PCR para Diagnóstico da raiva\"\npor: \"Técnicas moleculares baseadas em Reação de Transcriptase Reversa, seguida de Reação em Cadeia da Polimerase quantitativa (RT-qPCR) ou convencional (RT-PCR);\"\n\nNa descrição,  substituir \"Destina-se a substituir testes de inoculação em camundongos para isolamento viral.\" por \"Pode substituir o teste de inoculação em camundongos (Mouse inoculation Test -MIT) para diagnóstico da raiva animal.\"\n\nEm \"Uso de animais\", substituir \"subproduto de abatedouro\" por \"misto\"\n\nEm aplicação, substituir \"pesquisa básica\" por \" Teste diagnóstico\" \n\nStatus de validação: reconhecido no brasil"}, {"id": 13, "url": "https://3r-assist.vercel.app/explore", "object": "Teste de Imunofluorescência Direta (DFA) para Diagnóstico de Raiva", "user_id": null, "created_at": "2026-09-09T01:21:22.543089+00:00", "feedback_text": "Mudar o nome para: Técnica de Imunofluorescência Direta (Direct Fluorescent Antibody Test) - DFA Test;\n\nSubstituir a descrição atual por: \"Técnica de diagnóstico laboratorial utilizada para detectar antígenos do vírus da raiva em impressões ou esfregaços de tecido cerebral, por meio de anticorpos anti-rábicos conjugados à fluoresceína.\"\n\nEm \"uso de animais\", colocar: misto ou variável.\n\nSistema de testes: in vitro\n\nAplicação: teste diagnóstico\n\nStatus de validação: reconhecido (no Brasil)"}, {"id": 14, "url": "https://3r-assist.vercel.app/explore", "object": "Teste de Infecção em Cultura de Tecidos para Raiva (RTCIT)", "user_id": null, "created_at": "2026-09-09T02:51:26.720582+00:00", "feedback_text": "Substituir o nome atual por:\n\"Isolamento viral em cultivo celular (Rabies Tissue Culture Infection Test - RTCIT).\"\n\nUso de animais: misto ou variado\n\nAplicação: Teste diagnóstico\n\nStatus: reconhecido"}, {"id": 15, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda", "user_id": null, "created_at": "2026-09-11T19:52:25.658545+00:00", "feedback_text": "Corrigir o titulo para \" Método OECD TG 129 - estimativa da dose inicial para teste de toxicidade aguda oral sistêmica.\"\n\nObservação: na RN do CONCEA está \"OECD TG\", porém está errado, o correto seria OECD GD\", nesse caso, o que devemos fazer, manter errado para ficar como o do CONCEA ou corrigir?"}, {"id": 16, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda", "user_id": null, "created_at": "2026-09-11T20:02:03.382115+00:00", "feedback_text": "Substituir a descrição atual por:\n\n\"Ensaio de citotoxicidade basal in vitro baseado na captação de vermelho neutro (NRU), utilizando células BALB/c 3T3 ou queratinócitos humanos normais (NHK). O IC50 obtido é utilizado para estimar uma LD50 e auxiliar na seleção da dose inicial de testes de toxicidade aguda oral in vivo, com potencial de reduzir o número de animais utilizados.\"\n\nSe for possível incluir, coloque \"substituição\" tbm, que ele tbm pode atuar como método de substituição dependendo do regulamentador"}, {"id": 17, "url": "https://3r-assist.vercel.app/explore", "object": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda", "user_id": null, "created_at": "2026-09-11T20:08:13.846619+00:00", "feedback_text": "Colocar a referência da RN 18 do CONCEA.\nIsso vale para todos. Colocar a RN de reconhecimento de cada um"}, {"id": 18, "url": "https://3r-assist.vercel.app/explore", "object": "Corrosão cutânea in vitro: método de teste de epiderme humana reconstruída (RHE)", "user_id": null, "created_at": "2026-09-11T20:15:10.458017+00:00", "feedback_text": "Ajustar título para:\nMétodo OECD TG 431 – Corrosão dérmica in vitro: Teste da Epiderme Humana Reconstituída.\n\nAjustar descrição para:\nMétodo in vitro que utiliza epiderme humana reconstruída tridimensional, com estrato córneo funcional, para identificar substâncias e misturas corrosivas e não corrosivas com base na redução da viabilidade celular após períodos definidos de exposição.\n\nAjustar categoria de desfecho para \"corrosão cutânea\""}, {"id": 19, "url": "https://3r-assist.vercel.app/explore", "object": "Diretriz de Teste Baseada em Desempenho para Ensaios de Transativação In Vitro estavelmente Transfectados para Detectar Agonistas e Antagonistas do Receptor de Estrogênio", "user_id": null, "created_at": "2026-09-11T20:46:00.424121+00:00", "feedback_text": "Substituir o nome atual por:\nMétodo OECD TG 455 - Teste baseado na performance para ensaios in vitro de transativação transfectada estável para detectar agonistas e antagonistas de receptor estrogênico\n\nSubstituir a descrição atual por:  Diretriz baseada em desempenho para ensaios in vitro com linhagens celulares estavelmente transfectadas, utilizados para identificar substâncias com atividade agonista ou antagonista sobre receptores de estrogênio por meio da transativação de gene repórter.\nUso de animais: misco ou variável\nNa referencia, incluir link da RN do CONCEA, RN nº 56/2022. https://www.in.gov.br/web/dou/-/resolucao-n-56-de-5-de-outubro-de-2022-434544861"}, {"id": 20, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda", "user_id": null, "created_at": "2026-09-13T22:19:46.007488+00:00", "feedback_text": "Na categoria \"uso de animais\" tem que dizer que esse metodo usa produto de origem animal"}, {"id": 21, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Corrosão cutânea in vitro: método de teste de epiderme humana reconstruída (RHE)", "user_id": null, "created_at": "2026-09-13T22:33:16.821654+00:00", "feedback_text": "No \"uso de animais\", colocar \"misto ou variável\""}, {"id": 22, "url": "https://3r-assist.vercel.app/explore", "object": "Teste de Resistência Elétrica Transcutânea (TER)", "user_id": null, "created_at": "2026-09-25T19:46:56.559044+00:00", "feedback_text": "No título, mudar para:\nMétodo OECD TG430- Corrosão dérmica in vitro: teste de resistência elétrica transcutânea.\nEm \"uso de animais\", mudar para:\nAnimais mortos para obtenção de tecidos\nCategoria de desfecho: corrosão cutânea\n\nTrocar de substituição para redução e refinamento\n\nNo status de validação, alterar para Reconhecido, conforme foi explicado no grupo"}, {"id": 23, "url": "https://3r-assist.vercel.app/explore", "object": "Método de Teste de Barreira de Membrana in Vitro para Corrosão Cutânea", "user_id": null, "created_at": "2026-09-25T19:53:22.431714+00:00", "feedback_text": "Arrumar o título para: Método OECD TG 435- Teste de barreira de membrana in vitro.\n\nMudar a descrição para: Um método de teste de barreira de membrana in vitro que utiliza uma membrana artificial projetada para responder a produtos químicos corrosivos de maneira semelhante à pele para identificar produtos químicos corrosivos.\n\nCategoria de desfecho (endpoint): corrosão cutânea\n\nIncluir referência da RN 18 do CONCEA\n\nStatus de validação: Reconhecido"}, {"id": 24, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Irritação Cutânea In Vitro: Método de Teste de Epiderme Humana Reconstruída", "user_id": null, "created_at": "2026-09-25T19:58:22.848302+00:00", "feedback_text": "Mudar título para:\nMétodo OECD TG 439- Teste de irritação cutânea in vitro\n\nReferência: Incluir RN 18 do CONCEA\n\nStatus de validação: Reconhecido"}, {"id": 25, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Método de teste de vazamento de fluoresceína para identificação de corrosivos oculares e irritantes graves", "user_id": null, "created_at": "2026-09-25T20:03:21.04534+00:00", "feedback_text": "Mudar título para: Método OECD TG 460- Teste de permeação de fluoresceína.\n\nCategoria de desfecho (endpoint): corrosão ocular\n\nReferência: Incluir RN 18 CONCEA\n\nStatus de validação: Reconhecido"}, {"id": 26, "url": "https://3r-assist.vercel.app/explore/methods", "object": "Teste de Fototoxicidade in vitro 3T3 NRU", "user_id": null, "created_at": "2026-09-29T18:50:46.834979+00:00", "feedback_text": "Nome deve ser:\nMétodo OECD TG 432 - Teste de fototoxicidade in vitro 3T3 NRU.\n\nNe descrição trocar a palavra \"foto-citotoxicidade\" por \"fototoxicidade\".  Acrescentar (linhagem de fibroblastos murinos) depois de \"Balb/c 3T3\". Ficaria assim \"...viabilidade de células Balb/c 3T3 (linhagem de fibroblastos murinos)...\"\n\nUso de animais: material derivado de animal\n\nReferência: Incluir RN 18\n\nStatus de validação: Reconhecido"}]'::jsonb);
INSERT INTO public."methods" ("id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "ncit_id", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable") SELECT "id", "slug", "active", "name", "description", "animal_use", "test_system", "oecd_ref", "ncit_id", "source_citation", "source_doc_id", "source_db", "validation_status", "validation_doc_id", "replacement_rationale", "reduction_rationale", "refinement_rationale", "keywords", "text_for_embedding", "embedding_json", "created_at", "updated_at", "endpoints", "application_ids", "routes_applicable" FROM jsonb_populate_recordset(null::public."methods", '[{"id": 43, "name": {"en-us": "H295R Steroidogenesis Assay", "pt-br": "Ensaio de Esteroidogênese H295R"}, "slug": "oecd-tg456-h295r-steroidogenesis-assay", "active": false, "ncit_id": null, "keywords": {"en-us": ["steroidogenesis", "endocrine disruptor", "H295R", "hormone production"], "pt-br": ["esteroidogênese", "disruptor endócrino", "H295R", "produção hormonal"]}, "oecd_ref": "TG 456", "endpoints": [36], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-07T23:18:49.104491+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "An in vitro screen using the human H295R adreno-carcinoma cell line to assess chemical effects on the production of 17ß-estradiol and testosterone by measuring enzyme activity in the steroidogenesis pathway.", "pt-br": "Um ensaio in vitro utilizando a linhagem celular de adrenocarcinoma humano H295R para avaliar os efeitos químicos na produção de 17ß-estradiol e testosterona, medindo a atividade enzimática na via de esteroidogênese."}, "test_system": ["in_vitro"], "source_doc_id": 37, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 456 H295R Steroidogenesis Assay: an in vitro screen for chemical effects on the production of 17ß-estradiol and testosterone using human H295R adreno-carcinoma cells to assess endocrine activity.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Provides an in vitro alternative to identify substances that interfere with steroidogenesis without the need for animal models.", "pt-br": "Fornece uma alternativa in vitro para identificar substâncias que interferem na esteroidogênese sem a necessidade de modelos animais."}}, {"id": 3, "name": {"en-us": "In vitro skin corrosion: reconstructed human epidermis (RHE) test method", "pt-br": "Corrosão cutânea in vitro: método de teste de epiderme humana reconstruída (RHE)"}, "slug": "oecd-tg431-in-vitro-skin-corrosion", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin corrosion", "reconstructed human epidermis", "RHE", "cytotoxicity"], "pt-br": ["corrosão cutânea", "epiderme humana reconstruída", "RHE", "citotoxicidade"]}, "oecd_ref": "TG 431", "endpoints": [11], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "The test allows the identification of corrosive chemical substances and mixtures using a three-dimensional human skin model comprising at least a reconstructed epidermis with a functional stratum corneum, identifying corrosive potential based on cell viability measurements.", "pt-br": "O teste permite a identificação de substâncias e misturas químicas corrosivas utilizando um modelo de pele humana tridimensional compreendendo pelo menos uma epiderme reconstruída com um estrato córneo funcional, identificando o potencial corrosivo com base em medições de viabilidade celular."}, "test_system": ["in_vitro"], "source_doc_id": 18, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 431 In vitro skin corrosion: reconstructed human epidermis (RHE) test method. A non-animal test method for identifying corrosive chemicals using human skin models to measure cell viability.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The Test Guideline does not require the use of live animals or animal tissue for the assessment of skin corrosivity.", "pt-br": "A Diretriz de Teste não requer o uso de animais vivos ou tecido animal para a avaliação da corrosividade cutânea."}}, {"id": 14, "name": {"en-us": "LLNA: DA — Non-Radioactive Local Lymph Node Assay (ATP)", "pt-br": "LLNA:DA — Ensaio do Linfonodo Local Não Radioativo (ATP)"}, "slug": "oecd-tg442a-llna-da", "active": false, "ncit_id": null, "keywords": {"en-us": ["LLNA: DA", "skin sensitisation", "ATP bioluminescence", "lymphocyte proliferation"], "pt-br": ["LLNA: DA", "sensibilização cutânea", "bioluminescência de ATP", "proliferação linfocitária"]}, "oecd_ref": "TG 442A", "endpoints": [20], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "The Local Lymph Node Assay: DA (LLNA: DA) is a non-radioactive modification to the LLNA method for identifying potential skin sensitizing test substances by measuring lymphocyte proliferation in auricular lymph nodes via ATP content bioluminescence.", "pt-br": "O Local Lymph Node Assay: DA (LLNA: DA) é uma modificação não radioativa do método LLNA para identificar potenciais substâncias sensibilizantes cutâneas, medindo a proliferação de linfócitos nos linfonodos auriculares através da bioluminescência do conteúdo de ATP."}, "test_system": ["in_vivo"], "source_doc_id": 24, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 442A Local Lymph Node Assay: DA (LLNA: DA) is a non-radioactive in vivo test method for identifying skin sensitizing chemicals by measuring lymphocyte proliferation in auricular lymph nodes via ATP bioluminescence.", "reduction_rationale": null, "refinement_rationale": {"en-us": "The method acts as a non-radioactive modification to the traditional LLNA, improving safety and procedural requirements by using ATP bioluminescence instead of radioactive isotopes.", "pt-br": "O método atua como uma modificação não radioativa do LLNA tradicional, melhorando a segurança e os requisitos procedimentais ao usar bioluminescência de ATP em vez de isótopos radioativos."}, "replacement_rationale": null}, {"id": 15, "name": {"en-us": "Test No. 442B: Skin Sensitization: Local Lymph Node Assay: BrdU-ELISA or -FCM", "pt-br": "Teste Nº 442B: Sensibilização Cutânea: Ensaio de Linfonodo Local: BrdU-ELISA ou -FCM"}, "slug": "oecd-tg442b-llna-brdu-elisa-fcm", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin sensitization", "LLNA", "BrdU", "ELISA", "flow cytometry", "lymph nodes"], "pt-br": ["sensibilização cutânea", "LLNA", "BrdU", "ELISA", "citometria de fluxo", "linfonodos"]}, "oecd_ref": "TG 442B", "endpoints": [20], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A non-radioactive modification to the LLNA method for identifying potential skin sensitizing test chemicals by measuring the proliferation of lymphocytes in auricular lymph nodes using BrdU content, either by ELISA or Flow Cytometry.", "pt-br": "Uma modificação não radioativa do método LLNA para identificar produtos químicos com potencial de sensibilização cutânea, medindo a proliferação de linfócitos nos linfonodos auriculares usando o conteúdo de BrdU, seja por ELISA ou Citometria de Fluxo."}, "test_system": ["in_vivo"], "source_doc_id": 25, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 442B: Skin Sensitization: Local Lymph Node Assay (LLNA): BrdU-ELISA or -FCM is an in vivo test method identifying skin sensitizers by measuring lymphocyte proliferation in the auricular lymph nodes using BrdU-ELISA or Flow Cytometry.", "reduction_rationale": {"en-us": "[PENDENTE — ver category_3r]", "pt-br": "[PENDENTE — ver category_3r]"}, "refinement_rationale": {"en-us": "The method is a non-radioactive modification of the standard LLNA, avoiding the use of radioactive isotopes.", "pt-br": "O método é uma modificação não radioativa do LLNA padrão, evitando o uso de isótopos radioativos."}, "replacement_rationale": null}, {"id": 51, "name": {"en-us": "Fish, Short-term Toxicity Test on Embryo and Sac-Fry Stages", "pt-br": "Teste de toxicidade de curto prazo em estágios de embrião e alevino de peixe"}, "slug": "oecd-tg212-fish-embryo-sac-fry-toxicity", "active": false, "ncit_id": null, "keywords": {"en-us": ["fish", "embryo", "sac-fry", "aquatic toxicity", "embryo toxicity"], "pt-br": ["peixe", "embrião", "saco vitelino", "toxicidade aquática", "embriotoxicidade"]}, "oecd_ref": "TG 212", "endpoints": [41], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-08-08T01:55:45.952508+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "This test exposes fish life stages from newly fertilized egg to the end of the sac-fry stage to five concentrations of a test substance to assess lethal and sub-lethal effects.", "pt-br": "Este teste expõe estágios de vida de peixes desde o ovo recém-fertilizado até o final do estágio de saco vitelino a cinco concentrações de uma substância de teste para avaliar efeitos letais e subletais."}, "test_system": ["in_vivo"], "source_doc_id": 44, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [21], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 212: Fish, Short-term Toxicity Test on Embryo and Sac-Fry Stages. An in vivo toxicity test assessing lethal and sub-lethal effects of substances on fish embryos and sac-fry stages.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 36, "name": {"en-us": "Test No. 421: Reproduction/Developmental Toxicity Screening Test", "pt-br": "Teste Nº 421: Teste de Triagem de Toxicidade Reprodutiva/Desenvolvimental"}, "slug": "oecd-tg421-reproduction-developmental-toxicity-screening-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["reproductive toxicity", "developmental toxicity", "rat", "endocrine disruption"], "pt-br": ["toxicidade reprodutiva", "toxicidade desenvolvimental", "rato", "desregulação endócrina"]}, "oecd_ref": "TG 421", "endpoints": [25, 26], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-07-25T19:39:26.084168+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A screening test describing the effects of a test chemical on male and female reproductive performance in rats, including endocrine disruptor endpoints such as anogenital distance, nipple retention, and thyroid examination.", "pt-br": "Um teste de triagem que descreve os efeitos de uma substância química de teste no desempenho reprodutivo de machos e fêmeas em ratos, incluindo pontos finais de desreguladores endócrinos, como distância anogenital, retenção de mamilos e exame da tireoide."}, "test_system": ["in_vivo"], "source_doc_id": 48, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 421: Reproduction/Developmental Toxicity Screening Test. An in vivo study in rats designed to evaluate effects on reproductive performance and development, including endocrine disruptor endpoints.", "reduction_rationale": {"en-us": "This guideline is designed to generate limited information and serves as a screening tool that can be used for dose-range finding or initial hazard assessment, potentially reducing the need for more extensive studies if no toxic effects are observed.", "pt-br": "Esta diretriz gera informações limitadas e serve como ferramenta de triagem para definir faixas de dose ou realizar uma avaliação inicial de perigo. Se não forem observados efeitos tóxicos, pode reduzir a necessidade de estudos mais abrangentes."}, "refinement_rationale": {"en-us": "The method incorporates guiding principles for humane endpoints as outlined in OECD Guidance Document No. 19 to minimize animal suffering during safety evaluations.", "pt-br": "O método incorpora princípios para a definição de desfechos humanitários, conforme o Documento de Orientação nº 19 da OCDE, para minimizar o sofrimento dos animais durante as avaliações de segurança."}, "replacement_rationale": null}, {"id": 40, "name": {"en-us": "Short Time Exposure In Vitro Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage", "pt-br": "Método de Teste In Vitro de Exposição de Curta Duração para Identificação de Substâncias Químicas que Induzem Lesões Oculares Graves e Substâncias que Não Requerem Classificação para Irritação Ocular ou Lesão Ocular Grave"}, "slug": "oecd-tg491-short-time-exposure-in-vitro", "active": false, "ncit_id": null, "keywords": {"en-us": ["cytotoxicity", "SIRC cells", "MTT assay", "ocular hazard", "UN GHS Category 1"], "pt-br": ["citotoxicidade", "células SIRC", "ensaio MTT", "perigo ocular", "Categoria 1 GHS"]}, "oecd_ref": "TG 491", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": "animal_derived_material", "created_at": "2026-08-07T16:26:47.033481+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A cytotoxicity-based in vitro assay using Statens Seruminstitut Rabbit Cornea (SIRC) cells to identify chemicals inducing serious eye damage or those not requiring classification, based on relative cell viability measured by the MTT assay after a five-minute exposure.", "pt-br": "Um ensaio in vitro baseado em citotoxicidade usando células da córnea de coelho Statens Seruminstitut (SIRC) para identificar produtos químicos que induzem lesão ocular grave ou aqueles que não requerem classificação, com base na viabilidade celular relativa medida pelo ensaio MTT após uma exposição de cinco minutos."}, "test_system": ["in_vitro"], "source_doc_id": 34, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 491: Short Time Exposure In Vitro Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage. A cytotoxicity-based in vitro assay using SIRC cells and MTT assay to assess potential ocular damage.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The method is designed to identify chemicals inducing serious eye damage or those not requiring classification, allowing for the classification of eye hazard potential without the use of live animals.", "pt-br": "O método identifica substâncias que causam lesões oculares graves e substâncias que não requerem classificação quanto ao perigo ocular, permitindo essa avaliação sem o uso de animais vivos."}}, {"id": 37, "name": {"en-us": "Combined Repeated Dose Toxicity Study with the Reproduction/Developmental Toxicity Screening Test", "pt-br": "Estudo de Toxicidade por Doses Repetidas Combinado com o Teste de Triagem de Toxicidade Reprodutiva/Desenvolvimental"}, "slug": "oecd-tg422-combined-repeated-dose-reproduction-developmental-toxicity-screening", "active": false, "ncit_id": null, "keywords": {"en-us": ["reproductive toxicity", "developmental toxicity", "repeated dose toxicity", "endocrine disruption", "rat"], "pt-br": ["toxicidade reprodutiva", "toxicidade no desenvolvimento", "toxicidade por doses repetidas", "desregulação endócrina", "rato"]}, "oecd_ref": "TG 422", "endpoints": [18, 25, 26], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-07-25T19:44:29.744622+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A screening test guideline designed to assess the effects of a test chemical on male and female reproductive performance, developmental toxicity, and general repeated dose toxicity in rats, including endocrine disruptor endpoints.", "pt-br": "Uma diretriz de teste de triagem projetada para avaliar os efeitos de uma substância química de teste no desempenho reprodutivo de machos e fêmeas, toxicidade no desenvolvimento e toxicidade geral por doses repetidas em ratos, incluindo endpoints de desregulação endócrina."}, "test_system": ["in_vivo"], "source_doc_id": 49, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 422 Combined Repeated Dose Toxicity Study with the Reproduction/Developmental Toxicity Screening Test. This in vivo rat study assesses reproductive performance, developmental toxicity, and repeated dose toxicity using oral administration, updated to include endocrine disruptor endpoints.", "reduction_rationale": {"en-us": "Reduces the total number of animals required compared to conducting separate experiments for repeated dose and reproductive/developmental toxicity.", "pt-br": "Reduz o número total de animais necessários em comparação com a realização de ensaios separados de toxicidade por doses repetidas e toxicidade reprodutiva ou do desenvolvimento."}, "refinement_rationale": null, "replacement_rationale": null}, {"id": 56, "name": {"en-us": "Bacterial Endotoxins Test Using Recombinant Factor C (rFC)", "pt-br": "Teste de endotoxinas bacterianas com fator C recombinante (rFC)"}, "slug": "european-pharmacopoeia-bacterial-endotoxins-test-recombinant-reagents", "active": false, "ncit_id": null, "keywords": {"en-us": ["endotoxin", "recombinant factor C", "rFC", "pyrogenicity", "non-animal"], "pt-br": ["endotoxina", "Fator C recombinante", "rFC", "pirogenicidade", "não animal"]}, "oecd_ref": null, "endpoints": [50], "source_db": "European Pharmacopoeia", "animal_use": null, "created_at": "2026-08-08T02:22:54.115148+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "An in vitro method using recombinant factor C (rFC) and fluorimetric detection to detect or quantify bacterial endotoxins without horseshoe crab-derived lysate.", "pt-br": "Método in vitro que utiliza fator C recombinante (rFC) e detecção fluorimétrica para detectar ou quantificar endotoxinas bacterianas sem lisado derivado de caranguejos-ferradura."}, "test_system": ["in_vitro"], "source_doc_id": 10, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "European Pharmacopoeia 2.6.32 — Test for bacterial endotoxins using recombinant factor C (rFC). An in vitro assay that detects or quantifies Gram-negative bacterial endotoxins using rFC as an alternative to horseshoe crab amoebocyte lysate (LAL).", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Uses recombinant factor C instead of horseshoe crab-derived lysate, avoiding that animal-derived reagent.", "pt-br": "Utiliza fator C recombinante em vez de lisado derivado de caranguejos-ferradura, evitando esse reagente de origem animal."}}, {"id": 7, "name": {"en-us": "Isolated Chicken Eye Test Method", "pt-br": "Método de Teste de Olho de Frango Isolado"}, "slug": "oecd-tg438-isolated-chicken-eye", "active": false, "ncit_id": null, "keywords": {"en-us": ["ICE test", "eye irritation", "serious eye damage", "corneal opacity"], "pt-br": ["teste ICE", "irritação ocular", "dano ocular grave", "opacidade corneana"]}, "oecd_ref": "TG 438", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro test method using enucleated chicken eyes from slaughterhouses to identify chemicals inducing serious eye damage or those not requiring classification for eye irritation/damage based on corneal opacity, fluorescein retention, swelling, and morphological damage.", "pt-br": "Um método de teste in vitro utilizando olhos de frango enucleados de abatedouros para identificar substâncias químicas que induzem danos oculares graves ou que não requerem classificação para irritação/dano ocular com base na opacidade da córnea, retenção de fluoresceína, inchaço e dano morfológico."}, "test_system": ["ex_vivo"], "source_doc_id": 22, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 438 Isolated Chicken Eye Test Method for identifying chemicals inducing serious eye damage or not requiring classification for eye irritation using ex vivo enucleated chicken eyes.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Eliminates the need for laboratory animals by using eyes from chickens already killed for human consumption.", "pt-br": "Elimina a necessidade de animais de laboratório através do uso de olhos de frangos já abatidos para consumo humano."}}, {"id": 33, "name": {"en-us": "Direct rapid immunohistochemistry test (dRIT) for rabies diagnosis", "pt-br": "Teste rápido de imuno-histoquímica direta (dRIT) para diagnóstico da raiva"}, "slug": "rabies-direct-rapid-immunohistochemistry-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["rabies", "lyssavirus", "immunohistochemistry", "dRIT", "diagnosis"], "pt-br": ["raiva", "lyssavirus", "imuno-histoquímica", "dRIT", "diagnóstico"]}, "oecd_ref": "-", "endpoints": [54, 55], "source_db": "WOAH Terrestrial Manual 2025", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-07-03T19:31:06.464107+00:00", "updated_at": "2026-08-10T20:52:39.27359+00:00", "description": {"en-us": "A diagnostic method for rabies using streptavidin–biotin peroxidase staining to detect lyssavirus antigens in touch impressions of CNS tissues. It is an alternative to the direct fluorescent antibody (DFA) test that does not require a fluorescence microscope.", "pt-br": "Método para diagnóstico da raiva que detecta antígenos de lisavírus em impressões de tecidos do sistema nervoso central por coloração com peroxidase baseada em estreptavidina-biotina. Pode ser realizado sem microscópio de fluorescência, diferentemente do teste de imunofluorescência direta (DFA)."}, "test_system": ["ex_vivo"], "source_doc_id": 50, "embedding_json": null, "application_ids": [10], "source_citation": "World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729", "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Direct rapid immunohistochemistry test (dRIT) for rabies diagnosis. A diagnostic method for rabies using streptavidin–biotin peroxidase staining to detect lyssavirus antigens in touch impressions of CNS tissues as an alternative to DFA.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The dRIT is an alternative to the direct fluorescent antibody (DFA) test for rabies diagnosis and does not require fluorescence microscopy. For suitable samples, diagnosis can be performed without mouse inoculation.", "pt-br": "O dRIT é uma alternativa ao teste de imunofluorescência direta (DFA) para o diagnóstico da raiva e dispensa microscopia de fluorescência. Para amostras adequadas, o diagnóstico pode ser realizado sem inoculação em camundongos."}}, {"id": 47, "name": {"en-us": "Test No. 494: Vitrigel - Eye Irritancy Test Method", "pt-br": "Teste Nº 494: Método de Teste de Irritação Ocular Vitrigel"}, "slug": "oecd-tg494-vitrigel-eye-irritancy-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["Vitrigel", "eye irritation", "TEER", "human corneal epithelium", "hCE"], "pt-br": ["Vitrigel", "irritação ocular", "TEER", "epitélio corneano humano", "hCE"]}, "oecd_ref": "TG 494", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-08T01:37:30.475249+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro test method using human corneal epithelium (hCE) models to identify chemicals not requiring classification and labelling for eye irritation or serious eye damage by measuring changes in Transepithelial Electrical Resistance (TEER) values.", "pt-br": "Um método de teste in vitro utilizando modelos de epitélio corneano humano (hCE) para identificar produtos químicos que não requerem classificação e rotulagem para irritação ocular ou danos oculares graves, medindo alterações nos valores de Resistência Elétrica Transepitelial (TEER)."}, "test_system": ["in_vitro"], "source_doc_id": 41, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 494: Vitrigel-Eye Irritancy Test (EIT). An in vitro test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage using human corneal epithelium models and TEER measurements.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Allows the identification of chemicals not requiring classification and labelling for eye irritation or serious eye damage without the use of animal testing.", "pt-br": "Permite a identificação de produtos químicos que não requerem classificação e rotulagem para irritação ocular ou danos oculares graves sem o uso de testes em animais."}}, {"id": 38, "name": {"en-us": "Bacterial Endotoxins Test (LAL)", "pt-br": "Teste de Endotoxinas Bacterianas"}, "slug": "farmacopeia-MG5.5.2.7.3-02-teste-de-endotoxinas-bacterianas-lal", "active": false, "ncit_id": null, "keywords": {"en-us": ["LAL", "Limulus amebocyte lysate", "pyrogen", "endotoxin"], "pt-br": ["LAL", "lisado de amebócito de Limulus", "pirogênio", "endotoxina"]}, "oecd_ref": null, "endpoints": [48, 50], "source_db": "FARMACOPEIA_BR", "animal_use": "animal_derived_material", "created_at": "2026-07-25T19:54:12.778722+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "In vitro test using Limulus polyphemus or Tachypleus tridentatus amoebocyte lysate (LAL) to detect or quantify gram-negative bacterial endotoxins, including gel-clot, turbidimetric, and chromogenic methods.", "pt-br": "Teste in vitro utilizando lisado de amebócitos de Limulus polyphemus ou Tachypleus tridentatus (LAL) para detectar ou quantificar endotoxinas de bactérias gram-negativas, incluindo métodos de gelificação, turbidimétricos e cromogênicos."}, "test_system": ["in_vitro"], "source_doc_id": 1, "embedding_json": null, "application_ids": [3], "source_citation": "5.5.2.7.3 TESTE DE ENDOTOXINAS BACTERIANAS. Farmacopeia Brasileira, 7ª edição: Vol.1 MG5.5.2.7.3-02", "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Bacterial Endotoxins Test (LAL) is an in vitro assay using amoebocyte lysate from Limulus polyphemus or Tachypleus tridentatus to detect and quantify gram-negative bacterial endotoxins in pharmaceutical products, replacing traditional in vivo rabbit pyrogen testing.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Replaces the rabbit pyrogen test (in vivo).", "pt-br": "Substitui o teste de pirogênio em coelhos (in vivo)."}}, {"id": 18, "name": {"en-us": "Test No. 476: In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes", "pt-br": "Teste No. 476: Testes de Mutação Gênica em Células de Mamíferos In Vitro usando os genes Hprt e xprt"}, "slug": "oecd-tg476-in-vitro-mammalian-cell-gene-mutation-tests", "active": false, "ncit_id": null, "keywords": {"en-us": ["genotoxicity", "gene mutation", "HPRT", "XPRT", "mammalian cell"], "pt-br": ["genotoxicidade", "mutação gênica", "HPRT", "XPRT", "célula de mamífero"]}, "oecd_ref": "TG 476", "endpoints": [23], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-11T03:57:25.051436+00:00", "description": {"en-us": "The in vitro mammalian cell gene mutation test can be used to detect gene mutations induced by chemical substances measuring mutation at hypoxanthine-guanine phosphoribosyl transferase (HPRT) and xanthine-guanine phosphoribosyl transferase (XPRT) loci.", "pt-br": "O teste de mutação gênica em células de mamíferos in vitro pode ser usado para detectar mutações gênicas induzidas por substâncias químicas, medindo a mutação nos loci da hipoxantina-guanina fosforribosil transferase (HPRT) e xantina-guanina fosforribosil transferase (XPRT)."}, "test_system": ["in_vitro"], "source_doc_id": 31, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 476: In Vitro Mammalian Cell Gene Mutation Tests using the Hprt and xprt genes. Detects gene mutations induced by chemical substances in mammalian cell cultures.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 8, "name": {"en-us": "Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants", "pt-br": "Método de teste de vazamento de fluoresceína para identificação de corrosivos oculares e irritantes graves"}, "slug": "oecd-tg460-fluorescein-leakage", "active": false, "ncit_id": null, "keywords": {"en-us": ["fluorescein leakage", "ocular corrosion", "ocular irritation", "MDCK cells", "in vitro"], "pt-br": ["vazamento de fluoresceína", "corrosão ocular", "irritação ocular", "células MDCK", "in vitro"]}, "oecd_ref": "TG 460", "endpoints": [15], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro assay using a confluent monolayer of Madin-Darby Canine Kidney (MDCK) cells as a barrier to identify water-soluble ocular corrosives and severe irritants (UN GHS Category 1) by measuring increased fluorescein permeability resulting from impaired cell junctions.", "pt-br": "Um ensaio in vitro que utiliza uma monocamada confluente de células Madin-Darby Canine Kidney (MDCK) como barreira para identificar corrosivos oculares e irritantes graves (UN GHS Categoria 1), solúveis em água, medindo o aumento da permeabilidade à fluoresceína resultante do comprometimento das junções celulares."}, "test_system": ["in_vitro"], "source_doc_id": 29, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 460 Fluorescein Leakage Test Method for Identifying Ocular Corrosives and Severe Irritants. An in vitro assay using a confluent monolayer of MDCK cells to identify water-soluble ocular corrosives and severe irritants by measuring fluorescein permeability.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The method is used for identifying ocular corrosives and severe irritants as part of a tiered testing strategy, providing an alternative to animal testing.", "pt-br": "O método é utilizado para identificar corrosivos oculares e irritantes graves como parte de uma estratégia de teste em níveis, oferecendo uma alternativa ao teste em animais."}}, {"id": 17, "name": {"en-us": "Bacterial Reverse Mutation Test", "pt-br": "Teste de Mutação Reversa Bacteriana"}, "slug": "oecd-tg471-bacterial-reverse-mutation-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["Ames test", "genotoxicity", "mutagenicity", "Salmonella typhimurium", "Escherichia coli"], "pt-br": ["Teste de Ames", "genotoxicidade", "mutagenicidade", "Salmonella typhimurium", "Escherichia coli"]}, "oecd_ref": "TG 471", "endpoints": [23], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-11T03:57:25.051436+00:00", "description": {"en-us": "A test using amino-acid requiring strains of Salmonella typhimurium and Escherichia coli to detect point mutations by base substitutions or frameshifts, involving exposure of bacterial cells to a test substance with and without exogenous metabolic activation.", "pt-br": "Um teste utilizando cepas de Salmonella typhimurium e Escherichia coli que requerem aminoácidos para detectar mutações pontuais por substituições de bases ou frameshifts, envolvendo a exposição de células bacterianas a uma substância de teste com e sem ativação metabólica exógena."}, "test_system": ["in_vitro"], "source_doc_id": 30, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "oecd-tg471-bacterial-reverse-mutation-test: Bacterial Reverse Mutation Test. A genotoxicity assay using Salmonella typhimurium and Escherichia coli to identify point mutations via base substitutions or frameshifts.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 5, "name": {"en-us": "In Vitro Membrane Barrier Test Method for Skin Corrosion", "pt-br": "Método de Teste de Barreira de Membrana in Vitro para Corrosão Cutânea"}, "slug": "oecd-tg435-membrane-barrier-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin corrosion", "artificial membrane", "corrosive chemicals"], "pt-br": ["corrosão cutânea", "membrana artificial", "produtos químicos corrosivos"]}, "oecd_ref": "TG 435", "endpoints": [11], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro membrane barrier test method that utilizes an artificial membrane designed to respond to corrosive chemicals in a manner similar to animal skin in situ to identify corrosive chemicals.", "pt-br": "Um método de teste de barreira de membrana in vitro que utiliza uma membrana artificial projetada para responder a produtos químicos corrosivos de maneira semelhante à pele animal in situ para identificar produtos químicos corrosivos."}, "test_system": ["in_vitro"], "source_doc_id": 20, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "oecd-tg435-membrane-barrier-test In Vitro Membrane Barrier Test Method for Skin Corrosion. This method identifies corrosive chemicals using an artificial membrane barrier that mimics animal skin in situ.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Identifies corrosive chemicals using an artificial membrane, replacing the need for animal skin testing.", "pt-br": "Identifica produtos químicos corrosivos usando uma membrana artificial, substituindo a necessidade de testes em pele animal."}}, {"id": 19, "name": {"en-us": "Test No. 487: In Vitro Mammalian Cell Micronucleus Test", "pt-br": "Teste Nº 487: Teste de Micronúcleo em Células de Mamíferos In Vitro"}, "slug": "oecd-tg487-in-vitro-mammalian-cell-micronucleus-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["genotoxicity", "micronucleus", "clastogenic", "aneugenic"], "pt-br": ["genotoxicidade", "micronúcleo", "clastogênico", "aneugênico"]}, "oecd_ref": "TG 487", "endpoints": [22], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-11T03:57:25.051436+00:00", "description": {"en-us": "The in vitro micronucleus test is a genotoxicity test for the detection of micronuclei in the cytoplasm of interphase cells, originating from acentric chromosome fragments or whole chromosomes that are unable to migrate to the poles during anaphase.", "pt-br": "O teste de micronúcleo in vitro é um teste de genotoxicidade para a detecção de micronúcleos no citoplasma de células em interfase, originados de fragmentos cromossômicos acêntricos ou cromossomos inteiros que não conseguem migrar para os polos durante a anáfase."}, "test_system": ["in_vitro"], "source_doc_id": 32, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 487 In Vitro Mammalian Cell Micronucleus Test: A genotoxicity assay to detect clastogenic and aneugenic substances by identifying micronuclei in interphase cells.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 9, "name": {"en-us": "Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage", "pt-br": "Método de ensaio de Epitélio Corneo-símile Humano Reconstituído (RhCE) para identificação de produtos químicos que não requerem classificação e rotulagem para irritação ocular ou dano ocular grave"}, "slug": "oecd-tg492-rhce-eye-irritation", "active": false, "ncit_id": null, "keywords": {"en-us": ["RhCE", "eye irritation", "serious eye damage", "MTT assay", "in vitro", "UN GHS"], "pt-br": ["RhCE", "irritação ocular", "dano ocular grave", "ensaio MTT", "in vitro", "GHS da ONU"]}, "oecd_ref": "TG 492", "endpoints": [14], "source_db": "OECD_TG", "animal_use": "animal_derived_material", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro procedure using reconstructed human cornea-like epithelium (RhCE) to identify chemicals that do not require classification and labelling for eye irritation or serious eye damage according to UN GHS, based on the MTT assay to evaluate tissue cytotoxicity.", "pt-br": "Procedimento in vitro utilizando epitélio córneo-símile humano reconstituído (RhCE) para identificar produtos químicos que não requerem classificação e rotulagem para irritação ocular ou dano ocular grave de acordo com o GHS da ONU, baseado no ensaio MTT para avaliar a citotoxicidade tecidual."}, "test_system": ["in_vitro"], "source_doc_id": 33, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 492: Reconstructed human Cornea-like Epithelium (RhCE) test method for identifying chemicals not requiring classification and labelling for eye irritation or serious eye damage. An in vitro assay using RhCE tissue constructs to predict eye hazard potential via the MTT cytotoxicity test.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The RhCE test method serves as a non-animal alternative to evaluate eye hazard potential by mimicking human corneal epithelium properties.", "pt-br": "O método de ensaio RhCE serve como uma alternativa não animal para avaliar o potencial de risco ocular ao mimetizar as propriedades do epitélio da córnea humana."}}, {"id": 34, "name": {"en-us": "Rabies Tissue Culture Infection Test (RTCIT)", "pt-br": "Teste de Infecção em Cultura de Tecidos para Raiva (RTCIT)"}, "slug": "rabies-virus-isolation-tissue-culture", "active": false, "ncit_id": null, "keywords": {"en-us": ["rabies", "virus isolation", "cell culture", "RTCIT", "diagnosis"], "pt-br": ["raiva", "isolamento viral", "cultura de células", "RTCIT", "diagnóstico"]}, "oecd_ref": "-", "endpoints": [54, 57], "source_db": "WOAH Terrestrial Manual 2025", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-07-03T19:34:02.970307+00:00", "updated_at": "2026-08-10T20:52:39.27359+00:00", "description": {"en-us": "A diagnostic method for the detection and isolation of rabies virus in suspect animal brain tissue samples using neuroblastoma cell cultures (e.g., N2a), intended to replace the mouse inoculation test.", "pt-br": "Um método diagnóstico para a detecção e isolamento do vírus da raiva em amostras de tecido cerebral de animais suspeitos utilizando culturas de células de neuroblastoma (ex: N2a), com a finalidade de substituir o teste de inoculação em camundongos."}, "test_system": ["in_vitro"], "source_doc_id": 50, "embedding_json": null, "application_ids": [10], "source_citation": "World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729", "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Rabies Tissue Culture Infection Test (RTCIT) is an in vitro diagnostic method for the detection and isolation of rabies virus in animal brain samples, designed as a replacement for animal-based mouse inoculation tests.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Wherever possible, virus isolation in cell culture should replace mouse inoculation tests to avoid the use of animals.", "pt-br": "Sempre que possível, o isolamento viral em cultura de células deve substituir os testes de inoculação em camundongos para evitar o uso de animais."}}, {"id": 13, "name": {"en-us": "Local Lymph Node Assay (LLNA)", "pt-br": "Ensaio do Linfonodo Local (LLNA)"}, "slug": "oecd-tg429-local-lymph-node-assay", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin sensitisation", "LLNA", "mouse", "lymphocyte proliferation"], "pt-br": ["sensibilização cutânea", "LLNA", "camundongo", "proliferação de linfócitos"]}, "oecd_ref": "TG 429", "endpoints": [20], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "The Local Lymph Node Assay (LLNA) is a method for identifying skin sensitizers by measuring the proliferation of lymphocytes in the auricular lymph nodes draining the site of chemical application in mice.", "pt-br": "O Local Lymph Node Assay (LLNA) é um método para identificar sensibilizantes cutâneos medindo a proliferação de linfócitos nos linfonodos auriculares que drenam o local de aplicação química em camundongos."}, "test_system": ["in_vivo"], "source_doc_id": 16, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 429 Local Lymph Node Assay (LLNA). A test method for identifying skin sensitizers by measuring lymphocyte proliferation in the auricular lymph nodes of mice following dermal application.", "reduction_rationale": {"en-us": "A reduced LLNA approach is described as an option which could use up to 40% fewer animals.", "pt-br": "Uma abordagem LLNA reduzida é descrita como uma opção que pode utilizar até 40% menos animais."}, "refinement_rationale": null, "replacement_rationale": null}, {"id": 25, "name": {"en-us": "Test No. 425: Acute Oral Toxicity: Up-and-Down Procedure", "pt-br": "Teste No. 425: Toxicidade Aguda Oral: Procedimento Up-and-Down"}, "slug": "oecd-tg425-acute-oral-toxicity-up-and-down-procedure", "active": false, "ncit_id": null, "keywords": {"en-us": ["LD50", "acute oral toxicity", "up-and-down procedure", "rodents"], "pt-br": ["DL50", "toxicidade aguda oral", "procedimento up-and-down", "roedores"]}, "oecd_ref": "TG 425", "endpoints": [17], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An acute oral toxicity test method using an up-and-down procedure in rodents to estimate the LD50 and classify substances according to the GHS.", "pt-br": "Um método de teste de toxicidade aguda oral utilizando um procedimento up-and-down em roedores para estimar a DL50 e classificar substâncias de acordo com o GHS."}, "test_system": ["in_vivo"], "source_doc_id": 14, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 425 Acute Oral Toxicity: Up-and-Down Procedure. A method to estimate LD50 and classify acute toxicity via oral administration in rodents.", "reduction_rationale": null, "refinement_rationale": {"en-us": "[PENDENTE — ver category_3r]", "pt-br": "[PENDENTE — ver category_3r]"}, "replacement_rationale": null}, {"id": 30, "name": {"en-us": "Direct Fluorescent Antibody (DFA) Test for Rabies Diagnosis", "pt-br": "Teste de Imunofluorescência Direta (DFA) para Diagnóstico de Raiva"}, "slug": "rabies-direct-fluorescent-antibody-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["rabies", "DFA", "diagnostic", "lyssavirus"], "pt-br": ["raiva", "DFA", "diagnóstico", "lyssavirus"]}, "oecd_ref": "-", "endpoints": [54, 55], "source_db": "WOAH Terrestrial Manual 2025", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-07-03T18:33:41.961288+00:00", "updated_at": "2026-08-10T20:52:39.27359+00:00", "description": {"en-us": "A laboratory diagnostic technique used to identify rabies virus antigen in brain tissue impression smears using FITC-labelled anti-rabies antibody conjugate.", "pt-br": "Uma técnica de diagnóstico laboratorial usada para identificar antígenos do vírus da raiva em esfregaços de tecido cerebral usando conjugado de anticorpo anti-raiva marcado com FITC."}, "test_system": ["ex_vivo"], "source_doc_id": 50, "embedding_json": null, "application_ids": [10], "source_citation": "World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729", "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Direct Fluorescent Antibody (DFA) Test for Rabies Diagnosis. Diagnostic method for identifying Lyssavirus antigen in brain tissue using immunofluorescence, recommended by WHO and WOAH as a primary diagnostic test.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The text notes that virus isolation in cell culture should replace mouse inoculation tests where possible.", "pt-br": "O texto observa que o isolamento viral em cultura de células deve substituir os testes de inoculação em camundongos, sempre que possível."}}, {"id": 21, "name": {"en-us": "Test No. 428: Skin Absorption: In Vitro Method", "pt-br": "Teste Nº 428: Absorção Cutânea: Método In Vitro"}, "slug": "oecd-tg428-skin-absorption-in-vitro", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin absorption", "diffusion cell", "percutaneous absorption"], "pt-br": ["absorção cutânea", "célula de difusão", "absorção percutânea"]}, "oecd_ref": "TG 428", "endpoints": [3], "source_db": "OECD_TG", "animal_use": "mixed_or_variable", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro method using diffusion cells with skin samples (human or animal, viable or non-viable) to measure the percutaneous absorption of test substances applied to the skin surface.", "pt-br": "Um método in vitro usando células de difusão com amostras de pele (humana ou animal, viável ou não viável) para medir a absorção percutânea de substâncias de teste aplicadas na superfície da pele."}, "test_system": ["in_vitro"], "source_doc_id": 15, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 428 Skin Absorption: In Vitro Method. A method for measuring the percutaneous absorption of test substances using skin samples in diffusion cells to assess chemical safety.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 4, "name": {"en-us": "Transcutaneous Electrical Resistance (TER) Test", "pt-br": "Teste de Resistência Elétrica Transcutânea (TER)"}, "slug": "oecd-tg430-ter-corrosion", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin corrosion", "TER", "transcutaneous electrical resistance", "corrosive"], "pt-br": ["corrosão cutânea", "TER", "resistência elétrica transcutânea", "corrosivo"]}, "oecd_ref": "TG 430", "endpoints": [11], "source_db": "OECD_TG", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A test method that utilizes rat skin discs to identify corrosives by their ability to produce a loss of normal stratum corneum integrity and barrier function as measured by transcutaneous electrical resistance.", "pt-br": "Um método de teste que utiliza discos de pele de rato para identificar corrosivos pela sua capacidade de produzir uma perda da integridade normal do estrato córneo e da função de barreira, medida através da resistência elétrica transcutânea."}, "test_system": ["ex_vivo"], "source_doc_id": 17, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 430: In Vitro Skin Corrosion: Transcutaneous Electrical Resistance Test Method (TER). This method addresses the human health endpoint skin corrosion using rat skin discs to identify corrosives by measuring loss of stratum corneum integrity and barrier function via electrical resistance.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The method uses ex vivo skin discs to identify corrosive chemicals, avoiding the use of live animals for this endpoint.", "pt-br": "O método utiliza discos de pele ex vivo para identificar produtos químicos corrosivos, evitando o uso de animais vivos para este endpoint."}}, {"id": 54, "name": {"en-us": "Test No. 319A: Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP)", "pt-br": "Teste nº 319A: Determinação da depuração intrínseca in vitro usando hepatócitos de truta arco-íris criopreservados (RT-HEP)"}, "slug": "oecd-tg319a-rt-hep-clearance", "active": false, "ncit_id": null, "keywords": {"en-us": ["rainbow trout", "hepatocytes", "intrinsic clearance", "metabolism", "bioaccumulation", "substrate depletion"], "pt-br": ["truta arco-íris", "hepatócitos", "depuração intrínseca", "metabolismo", "bioacumulação", "depleção de substrato"]}, "oecd_ref": "TG 319A", "endpoints": [5], "source_db": "OECD_TG", "animal_use": "animals_killed_for_tissue", "created_at": "2026-08-08T02:08:24.580834+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "This Test Guideline describes the use of cryopreserved rainbow trout (Oncorhynchus mykiss) hepatocytes (RT-HEP) as a metabolising system to determine the intrinsic clearance (CL, IN VITRO, INT) of a test chemical using a substrate depletion approach.", "pt-br": "Esta Diretriz de Teste descreve o uso de hepatócitos de truta arco-íris (Oncorhynchus mykiss) criopreservados (RT-HEP) como um sistema de metabolização para determinar a depuração intrínseca (CL, IN VITRO, INT) de um produto químico de teste usando uma abordagem de depleção de substrato."}, "test_system": ["in_vitro"], "source_doc_id": 46, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 319A: Determination of in vitro intrinsic clearance using cryopreserved rainbow trout hepatocytes (RT-HEP). This method uses rainbow trout liver cells to measure metabolic clearance rates of chemicals, helping to refine in silico bioaccumulation predictions.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 53, "name": {"en-us": "Fish Embryo Acute Toxicity (FET) Test", "pt-br": "Teste de Toxicidade Aguda em Embriões de Peixe (FET)"}, "slug": "oecd-tg236-fish-embryo-acute-toxicity-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["zebrafish", "embryo", "acute toxicity", "Danio rerio"], "pt-br": ["peixe-zebra", "embrião", "toxicidade aguda", "Danio rerio"]}, "oecd_ref": "TG 236", "endpoints": [41], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-08-08T02:04:38.078573+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "An acute toxicity test using zebrafish embryos (Danio rerio) exposed to chemicals for 96 hours to determine lethality based on apical observations.", "pt-br": "Um teste de toxicidade aguda usando embriões de peixe-zebra (Danio rerio) expostos a substâncias químicas por 96 horas para determinar a letalidade com base em observações apicais."}, "test_system": ["in_vivo"], "source_doc_id": 45, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [21], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "oecd-tg236-fet-test: Fish Embryo Acute Toxicity (FET) Test. An acute toxicity test using zebrafish embryos (Danio rerio) to determine lethality based on apical observations over a 96-hour period.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The method uses embryonic stages of fish, which are considered a replacement for acute toxicity tests on juvenile or adult fish.", "pt-br": "O método utiliza estágios embrionários de peixes, considerados uma alternativa a ensaios de toxicidade aguda com peixes juvenis ou adultos."}}, {"id": 6, "name": {"en-us": "Bovine Corneal Opacity and Permeability (BCOP) Assay", "pt-br": "Ensaio de Opacidade e Permeabilidade da Córnea Bovina (BCOP)"}, "slug": "oecd-tg437-bcop", "active": false, "ncit_id": null, "keywords": {"en-us": ["BCOP", "ocular toxicity", "cornea", "eye irritation", "serious eye damage"], "pt-br": ["BCOP", "toxicidade ocular", "córnea", "irritação ocular", "dano ocular grave"]}, "oecd_ref": "TG 437", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro test method that uses isolated bovine corneas from cattle slaughtered for commercial purposes to identify chemicals inducing serious eye damage or chemicals not requiring classification for eye irritation/damage.", "pt-br": "Um método de teste in vitro que utiliza córneas bovinas isoladas de gado abatido para fins comerciais para identificar produtos químicos que induzem danos oculares graves ou produtos químicos que não requerem classificação para irritação/dano ocular."}, "test_system": ["ex_vivo"], "source_doc_id": 21, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 437 Bovine Corneal Opacity and Permeability Test Method for identifying chemicals inducing serious eye damage or not requiring classification for eye irritation using isolated bovine corneas.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The BCOP test method avoids the use of laboratory animals by using isolated corneas from the eyes of cattle slaughtered for commercial purposes.", "pt-br": "O método de teste BCOP evita o uso de animais de laboratório através do uso de córneas isoladas de olhos de gado abatido para fins comerciais."}}, {"id": 41, "name": {"en-us": "Performance-Based Test Guideline for Stably Transfected Transactivation In Vitro Assays to Detect Estrogen Receptor Agonists and Antagonists", "pt-br": "Diretriz de Teste Baseada em Desempenho para Ensaios de Transativação In Vitro estavelmente Transfectados para Detectar Agonistas e Antagonistas do Receptor de Estrogênio"}, "slug": "oecd-tg455-stably-transfected-transactivation-in-vitro-assays", "active": false, "ncit_id": null, "keywords": {"en-us": ["estrogen receptor", "transactivation", "endocrine disruptors", "luciferase", "in vitro assay"], "pt-br": ["receptor de estrogênio", "transativação", "desreguladores endócrinos", "luciferase", "ensaio in vitro"]}, "oecd_ref": "TG 455", "endpoints": [33], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-07T19:40:46.720127+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "A performance-based test guideline for in vitro assays using stably transfected cell lines to detect estrogen receptor agonists and antagonists by measuring ER-dependent transcription via luciferase reporter gene expression.", "pt-br": "Uma diretriz de teste baseada em desempenho para ensaios in vitro usando linhagens celulares estavelmente transfectadas para detectar agonistas e antagonistas do receptor de estrogênio, medindo a transcrição dependente de ER através da expressão do gene repórter luciferase."}, "test_system": ["in_vitro"], "source_doc_id": 35, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 455 Performance-Based Test Guideline for Stably Transfected Transactivation In Vitro Assays to Detect Estrogen Receptor Agonists and Antagonists. Detects endocrine activity using in vitro luciferase reporter assays.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The test method allows for the identification of endocrine disrupting chemicals using in vitro assays as an alternative to animal testing.", "pt-br": "O método de teste permite a identificação de substâncias químicas desreguladoras endócrinas usando ensaios in vitro como alternativa aos testes em animais."}}, {"id": 44, "name": {"en-us": "OECD TG 458: Stably Transfected Human Androgen Receptor Transcriptional Activation Assay", "pt-br": "OECD TG 458: Ensaio de Ativação Transcricional do Receptor de Andrógeno Humano estavelmente transfectado"}, "slug": "oecd-tg458-androgen-receptor-transactivational-assay", "active": false, "ncit_id": null, "keywords": {"en-us": ["androgen receptor", "transcriptional activation", "endocrine disruptor", "ARTA assay"], "pt-br": ["receptor de andrógeno", "ativação transcricional", "desregulador endócrino", "ensaio ARTA"]}, "oecd_ref": "TG 458", "endpoints": [34], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-08T01:15:26.444465+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "In vitro assay using Androgen Receptor TransActivation (ARTA) in stably transfected cell lines (AR-EcoScreen, AR-CALUX, 22Rv1/MMTV_GR-KO) to detect androgenic agonist and antagonist activity of chemicals.", "pt-br": "Ensaio in vitro usando Ativação Transcricional do Receptor de Andrógeno (ARTA) em linhagens celulares estavelmente transfectadas (AR-EcoScreen, AR-CALUX, 22Rv1/MMTV_GR-KO) para detectar atividade agonista e antagonista androgênica de produtos químicos."}, "test_system": ["in_vitro"], "source_doc_id": 38, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 458: Stably Transfected Human Androgen Receptor Transcriptional Activation Assay. This in vitro test method uses stably transfected human cell lines to detect androgen receptor agonists and antagonists by measuring luciferase reporter gene expression.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 45, "name": {"en-us": "Test No. 473: In Vitro Mammalian Chromosomal Aberration Test", "pt-br": "Test No. 473: Teste de Aberração Cromossômica em Células de Mamíferos In Vitro"}, "slug": "oecd-tg473-in-vitro-mammalian-chromosomal-aberration-test", "active": false, "ncit_id": null, "keywords": {"en-us": ["genotoxicity", "chromosomal aberration", "mammalian cells", "in vitro"], "pt-br": ["genotoxicidade", "aberração cromossômica", "células de mamíferos", "in vitro"]}, "oecd_ref": "TG 473", "endpoints": [23], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-08T01:25:14.50795+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "The purpose of the in vitro chromosome aberration test is to identify agents that cause structural chromosome aberrations in cultured mammalian somatic cells.", "pt-br": "O objetivo do teste de aberração cromossômica in vitro é identificar agentes que causam aberrações cromossômicas estruturais em células somáticas de mamíferos cultivadas."}, "test_system": ["in_vitro"], "source_doc_id": 39, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 473: In Vitro Mammalian Chromosomal Aberration Test. An in vitro test method for identifying structural chromosome aberrations in cultured mammalian somatic cells for chemical safety assessment.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 35, "name": {"en-us": "Rabies RT-PCR Diagnostic Assay", "pt-br": "Ensaios de RT-PCR para Diagnóstico de Raiva"}, "slug": "rabies-rt-pcr-diagnostic-assay", "active": false, "ncit_id": null, "keywords": {"en-us": ["Rabies", "Lyssavirus", "RT-PCR", "Diagnosis", "Molecular diagnostics", "Virus detection"], "pt-br": ["Raiva", "Lyssavirus", "RT-PCR", "Diagnóstico", "Diagnóstico molecular", "Detecção de vírus"]}, "oecd_ref": "-", "endpoints": [54, 56], "source_db": "WOAH Terrestrial Manual 2025", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-07-03T19:36:13.494447+00:00", "updated_at": "2026-08-10T20:52:39.27359+00:00", "description": {"en-us": "Laboratory technique for the detection and identification of lyssavirus RNA in suspect animal brain tissue samples using conventional or real-time reverse-transcription polymerase chain reaction (RT-PCR) assays. Intended to replace mouse inoculation tests for virus isolation.", "pt-br": "Técnica laboratorial para detecção e identificação de RNA de lyssavírus em amostras de tecido cerebral animal suspeito, utilizando ensaios de reação em cadeia da polimerase com transcrição reversa (RT-PCR) convencional ou em tempo real. Destina-se a substituir testes de inoculação em camundongos para isolamento viral."}, "test_system": ["in_vitro"], "source_doc_id": 50, "embedding_json": null, "application_ids": [10], "source_citation": "World Organisation for Animal Health. (2025). Rabies (infection with rabies virus and other lyssaviruses) (Chapter 3.1.19). In Manual of Diagnostic Tests and Vaccines for Terrestrial Animals (10th ed.). WOAH. https://doi.org/10.20506/woah.3729", "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Rabies RT-PCR Diagnostic Assay: A laboratory technique for the detection of lyssavirus RNA in animal brain tissue, serving as an alternative to mouse inoculation tests for rabies diagnosis.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Wherever possible, virus isolation in cell culture or RT-PCR should replace mouse inoculation tests for rabies diagnosis.", "pt-br": "Sempre que possível, o isolamento viral em cultura de células ou RT-PCR deve substituir os testes de inoculação em camundongos para o diagnóstico de raiva."}}, {"id": 55, "name": {"en-us": "Test No. 319B: Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9)", "pt-br": "Teste nº 319B: Determinação do clearance intrínseco in vitro utilizando fração subcelular S9 de fígado de truta arco-íris (RT-S9)"}, "slug": "oecd-tg319b-rt-s9-intrinsic-clearance", "active": false, "ncit_id": null, "keywords": {"en-us": ["rainbow trout", "S9 fraction", "intrinsic clearance", "metabolism", "substrate depletion"], "pt-br": ["truta arco-íris", "fração S9", "clearance intrínseco", "metabolismo", "depleção de substrato"]}, "oecd_ref": "TG 319B", "endpoints": [5], "source_db": "OECD_TG", "animal_use": "slaughterhouse_byproduct", "created_at": "2026-08-08T02:11:59.826418+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "The test guideline describes the use of rainbow trout liver S9 sub-cellular fraction as a metabolising system to determine the in vitro intrinsic clearance of a test chemical using a substrate depletion approach.", "pt-br": "A diretriz de teste descreve o uso da fração subcelular S9 de fígado de truta arco-íris como um sistema metabolizante para determinar o clearance intrínseco in vitro de uma substância química de teste usando uma abordagem de depleção de substrato."}, "test_system": ["in_vitro"], "source_doc_id": 47, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "oecd-tg319b-rt-s9-intrinsic-clearance, Test No. 319B: Determination of in vitro intrinsic clearance using rainbow trout liver S9 sub-cellular fraction (RT-S9). This method uses rainbow trout liver S9 sub-cellular fraction to determine the in vitro intrinsic clearance of a chemical for bioaccumulation prediction.", "reduction_rationale": {"en-us": "The use of liver S9 sub-cellular fraction allows for the determination of metabolic clearance without the need for live fish testing.", "pt-br": "O uso da fração subcelular S9 do fígado permite a determinação do clearance metabólico sem a necessidade de testes em peixes vivos."}, "refinement_rationale": null, "replacement_rationale": null}, {"id": 42, "name": {"en-us": "Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity", "pt-br": "Diretriz de Teste Baseada em Desempenho para Ensaios In Vitro com Receptor de Estrogênio Humano Recombinante (hrER) para Detectar Substâncias com Afinidade de Ligação ao RE"}, "slug": "oecd-tg493-hrer-binding-assay", "active": false, "ncit_id": null, "keywords": {"en-us": ["estrogen receptor", "endocrine disruption", "binding affinity", "in vitro", "hrER"], "pt-br": ["receptor de estrogênio", "disrupção endócrina", "afinidade de ligação", "in vitro", "hrER"]}, "oecd_ref": "TG 493", "endpoints": [33], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-07T22:56:45.637179+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "A performance-based test guideline for in vitro assays using human recombinant estrogen receptor alpha (ERα) to measure the ability of test chemicals to compete with a radiolabeled ligand for binding to the receptor, thereby identifying potential ER binders.", "pt-br": "Uma diretriz de teste baseada em desempenho para ensaios in vitro utilizando receptor de estrogênio alfa humano recombinante (ERα) para medir a capacidade de substâncias de teste competirem com um ligante radiomarcado pela ligação ao receptor, identificando assim potenciais ligantes do RE."}, "test_system": ["in_vitro"], "source_doc_id": 36, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 493: Performance-Based Test Guideline for Human Recombinant Estrogen Receptor (hrER) In Vitro Assays to Detect Chemicals with ER Binding Affinity. This method describes in vitro assays to identify substances with estrogen receptor binding affinity using human recombinant ERα.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Provides an in vitro alternative for identifying estrogen receptor binders, avoiding the use of live animal models for initial screening and prioritization.", "pt-br": "Fornece uma alternativa in vitro para a identificação de ligantes do receptor de estrogênio, evitando o uso de modelos animais vivos para triagem inicial e priorização."}}, {"id": 46, "name": {"en-us": "In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene", "pt-br": "Testes de Mutação Gênica em Células de Mamíferos In Vitro Usando o Gene da Timidina Quinase"}, "slug": "oecd-tg490-in-vitro-mammalian-cell-gene-mutation-tests", "active": false, "ncit_id": null, "keywords": {"en-us": ["genotoxicity", "gene mutation", "thymidine kinase", "L5178Y", "TK6", "mouse lymphoma assay"], "pt-br": ["genotoxicidade", "mutação gênica", "timidina quinase", "L5178Y", "TK6", "ensaio de linfoma de camundongo"]}, "oecd_ref": "TG 490", "endpoints": [23], "source_db": "OECD_TG", "animal_use": "animals_killed_for_tissue", "created_at": "2026-08-08T01:30:31.455682+00:00", "updated_at": "2026-08-10T21:45:59.379161+00:00", "description": {"en-us": "The in vitro mammalian cell gene mutation test using the thymidine kinase (tk) gene involves two distinct assays (MLA using L5178Y tk+/-3.7.2C cells and the TK6 assay using TK6 tk+/- cells) to detect gene mutations and chromosomal events induced by chemical substances in cells exposed with and without metabolic activation.", "pt-br": "O teste de mutação gênica em células de mamíferos in vitro usando o gene da timidina quinase (tk) envolve dois ensaios distintos (MLA usando células L5178Y tk+/-3.7.2C e o ensaio TK6 usando células TK6 tk+/-) para detectar mutações gênicas e eventos cromossômicos induzidos por substâncias químicas em células expostas com e sem ativação metabólica."}, "test_system": ["in_vitro"], "source_doc_id": 40, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 490: In Vitro Mammalian Cell Gene Mutation Tests Using the Thymidine Kinase Gene. An in vitro test method for detecting gene mutations and chromosomal events using mouse lymphoma or TK6 cells.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": null}, {"id": 1, "name": {"en-us": "In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method", "pt-br": "Irritação Cutânea In Vitro: Método de Teste de Epiderme Humana Reconstruída"}, "slug": "oecd-tg439-reconstructed-human-epidermis-skin-irritation", "active": false, "ncit_id": null, "keywords": {"en-us": ["RhE", "skin irritation", "MTT assay", "in vitro"], "pt-br": ["RhE", "irritação cutânea", "ensaio MTT", "in vitro"]}, "oecd_ref": "TG 439", "endpoints": [10], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro procedure using reconstructed human epidermis (RhE) to identify irritant chemicals (substances and mixtures) by measuring cell viability via MTT reduction, mimicking the physiological properties of human skin.", "pt-br": "Procedimento in vitro utilizando epiderme humana reconstruída (RhE) para identificar substâncias químicas irritantes (substâncias e misturas) através da medição da viabilidade celular via redução do MTT, mimetizando as propriedades fisiológicas da pele humana."}, "test_system": ["in_vitro"], "source_doc_id": 23, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 439: In Vitro Skin Irritation: Reconstructed Human Epidermis Test Method. An in vitro test method for hazard identification of skin irritants using reconstructed human epidermis (RhE) and MTT reduction.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The procedure may be used as a stand-alone replacement test for in vivo skin irritation testing, or as a partial replacement test within a tiered testing strategy.", "pt-br": "O procedimento pode ser utilizado como teste substitutivo autônomo para ensaios de irritação cutânea in vivo ou como teste de substituição parcial no âmbito de uma estratégia de ensaios em etapas."}}, {"id": 24, "name": {"en-us": "Acute Oral Toxicity – Acute Toxic Class Method", "pt-br": "Toxicidade Oral Aguda – Método da Classe de Toxicidade Aguda"}, "slug": "oecd-tg423-acute-oral-toxicity-acute-toxic-class-method", "active": false, "ncit_id": null, "keywords": {"en-us": ["acute oral toxicity", "LD50", "hazard classification", "fixed dose"], "pt-br": ["toxicidade oral aguda", "DL50", "classificação de perigo", "dose fixa"]}, "oecd_ref": "TG 423", "endpoints": [17], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A stepwise procedure with the use of 3 animals of a single sex per step, designed to rank substances for classification purposes and hazard assessment using fixed doses.", "pt-br": "Um procedimento em etapas com o uso de 3 animais de um único sexo por etapa, projetado para classificar substâncias para fins de classificação e avaliação de perigo usando doses fixas."}, "test_system": ["in_vivo"], "source_doc_id": 13, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 423 Acute Oral Toxicity – Acute Toxic Class Method is an in vivo method for acute toxicity hazard classification using a stepwise procedure with fixed doses in rodents.", "reduction_rationale": {"en-us": "The method uses a stepwise procedure with a minimum number of animals per step and is able to rank substances while using very few animals compared to conventional acute toxicity tests.", "pt-br": "O método utiliza um procedimento em etapas com um número mínimo de animais por etapa e é capaz de classificar substâncias utilizando muito poucos animais em comparação com os testes convencionais de toxicidade aguda."}, "refinement_rationale": null, "replacement_rationale": null}, {"id": 22, "name": {"en-us": "Basal Cytotoxicity for Acute Toxicity Starting Dose Estimation", "pt-br": "Citotoxicidade Basal para Estimativa de Dose Inicial de Toxicidade Aguda"}, "slug": "oecd-gd129-cytotoxicity-starting-dose", "active": true, "ncit_id": null, "keywords": {"en-us": ["cytotoxicity", "neutral red uptake", "NRU", "acute oral toxicity", "starting dose", "3T3", "NHK"], "pt-br": ["citotoxicidade", "captação de vermelho neutro", "NRU", "toxicidade oral aguda", "dose inicial", "3T3", "NHK"]}, "oecd_ref": "GD 129", "endpoints": [17, 58], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "Cell-based assay (3T3 or NHK NRU) measuring basal cytotoxicity to estimate a starting dose for in vivo acute oral toxicity studies, reducing the number of animals used. Based on OECD GD 129 (NICEATM-ECVAM validation). Does not replace the in vivo test — reduces animal numbers in dose-finding.", "pt-br": "Ensaio celular (3T3 ou NHK NRU) que mede citotoxicidade basal para estimar dose inicial em estudos de toxicidade aguda oral in vivo, reduzindo o número de animais. Baseado no OECD GD 129 (validação NICEATM-ECVAM). Não substitui o teste in vivo — reduz número de animais na busca de dose."}, "test_system": ["in_vitro"], "source_doc_id": 11, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD-GD129 Guidance Document on Using Cytotoxicity Tests to Estimate Starting Doses for Acute Oral Systemic Toxicity Tests. This method uses in vitro Neutral Red Uptake (NRU) assays in 3T3 or NHK cells to estimate LD50 and refine starting doses for in vivo acute oral toxicity testing, reducing animal usage.", "reduction_rationale": {"en-us": "By estimating the starting dose for acute oral toxicity tests, the number of animals required to determine the LD50 can be reduced by up to 50% compared to default starting doses.", "pt-br": "Ao estimar a dose inicial para ensaios de toxicidade oral aguda, é possível reduzir em até 50% o número de animais necessários para determinar a DL50, em comparação com doses iniciais padrão."}, "refinement_rationale": null, "replacement_rationale": null}, {"id": 16, "name": {"en-us": "In Vitro 3T3 NRU Phototoxicity Test", "pt-br": "Teste de Fototoxicidade in vitro 3T3 NRU"}, "slug": "oecd-tg432-3t3-nru-phototoxicity", "active": false, "ncit_id": null, "keywords": {"en-us": ["phototoxicity", "Neutral Red Uptake", "3T3 cells", "photo-cytotoxicity"], "pt-br": ["fototoxicidade", "captação de vermelho neutro", "células 3T3", "foto-citotoxicidade"]}, "oecd_ref": "TG 432", "endpoints": [12], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A method to evaluate photo-cytotoxicity by comparing the relative reduction in viability of Balb/c 3T3 cells exposed to chemicals in the presence versus absence of light using the Neutral Red uptake assay.", "pt-br": "Um método para avaliar a foto-citotoxicidade comparando a redução relativa na viabilidade de células Balb/c 3T3 expostas a substâncias químicas na presença versus ausência de luz usando o ensaio de captação de Vermelho Neutro."}, "test_system": ["in_vitro"], "source_doc_id": 19, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 432: In Vitro 3T3 NRU Phototoxicity Test. This method evaluates photo-cytotoxicity by measuring the concentration-dependent reduction in Neutral Red dye uptake in Balb/c 3T3 cells when exposed to chemicals with or without light irradiation.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The test provides an alternative to in vivo phototoxicity testing by using in vitro cell cultures to assess chemical-induced cytotoxicity following irradiation.", "pt-br": "O teste fornece uma alternativa aos testes de fototoxicidade in vivo usando culturas celulares in vitro para avaliar a citotoxicidade induzida por substâncias químicas após irradiação."}}, {"id": 10, "name": {"en-us": "Test No. 442C: In Chemico Skin Sensitisation", "pt-br": "Test No. 442C: Sensibilização Cutânea In Chemico"}, "slug": "oecd-tg442c-in-chemico-skin-sensitisation", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin sensitisation", "protein reactivity", "DPRA", "ADRA", "kDPRA", "AOP", "molecular initiating event"], "pt-br": ["sensibilização cutânea", "reatividade proteica", "DPRA", "ADRA", "kDPRA", "AOP", "evento iniciador molecular"]}, "oecd_ref": "TG 442C", "endpoints": [20], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "This Test Guideline addresses the molecular initiating event of skin sensitisation, namely protein reactivity, by quantifying the reactivity of test chemicals towards model synthetic peptides or amino acid derivatives containing either lysine or cysteine. It includes three methods: DPRA, ADRA, and kDPRA.", "pt-br": "Esta Diretriz de Teste aborda o evento iniciador molecular da sensibilização cutânea, nomeadamente a reatividade proteica, quantificando a reatividade de substâncias químicas de teste em relação a peptídeos sintéticos modelo ou derivados de aminoácidos contendo lisina ou cisteína. Inclui três métodos: DPRA, ADRA e kDPRA."}, "test_system": ["in_chemico"], "source_doc_id": 26, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 442C In Chemico Skin Sensitisation: A test method series including DPRA, ADRA, and kDPRA addressing the skin sensitisation molecular initiating event of protein reactivity using model synthetic peptides.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The test methods provide in chemico alternatives for identifying skin sensitisers without the use of animals.", "pt-br": "Os métodos de teste fornecem alternativas in chemico para a identificação de sensibilizantes cutâneos sem o uso de animais."}}, {"id": 11, "name": {"en-us": "Test No. 442D: In Vitro Skin Sensitisation", "pt-br": "Teste Nº 442D: Sensibilização Cutânea In Vitro"}, "slug": "oecd-tg442d-in-vitro-skin-sensitisation", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin sensitisation", "keratinocyte activation", "AOP", "adverse outcome pathway", "in vitro"], "pt-br": ["sensibilização cutânea", "ativação de queratinócitos", "AOP", "via de desfecho adverso", "in vitro"]}, "oecd_ref": "TG 442D", "endpoints": [20], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A Key Event based Test Guideline addressing the human health hazard endpoint skin sensitisation, focusing on keratinocyte activation. It includes five in vitro methods: KeratinoSens, LuSens, EpiSensA, Epi2SensA, and α-Sens.", "pt-br": "Uma Diretriz de Teste baseada em Evento-Chave que aborda o endpoint de perigo à saúde humana sensibilização cutânea, com foco na ativação de queratinócitos. Inclui cinco métodos in vitro: KeratinoSens, LuSens, EpiSensA, Epi2SensA e α-Sens."}, "test_system": ["in_vitro"], "source_doc_id": 27, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 442D: In Vitro Skin Sensitisation. This guideline addresses skin sensitisation through keratinocyte activation and provides five in vitro test methods: KeratinoSens, LuSens, EpiSensA, Epi2SensA, and α-Sens, for discriminating skin sensitisers from non-sensitisers.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The test methods are used for supporting the discrimination between skin sensitisers and non-sensitisers as an alternative to animal testing.", "pt-br": "Os métodos de teste são usados para apoiar a discriminação entre sensibilizantes cutâneos e não sensibilizantes como uma alternativa aos testes em animais."}}, {"id": 23, "name": {"en-us": "Test No. 420: Acute Oral Toxicity - Fixed Dose Procedure", "pt-br": "Teste nº 420: Toxicidade Oral Aguda - Procedimento de Dose Fixa"}, "slug": "oecd-tg420-fixed-dose-procedure", "active": false, "ncit_id": null, "keywords": {"en-us": ["acute oral toxicity", "fixed dose procedure", "rat", "gavage"], "pt-br": ["toxicidade oral aguda", "procedimento de dose fixa", "rato", "gavagem"]}, "oecd_ref": "TG 420", "endpoints": [17], "source_db": "OECD_TG", "animal_use": "live_animals", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "The Fixed Dose Procedure is a method for the assessment of acute oral toxicity in rats, using a stepwise approach to identify doses that produce signs of toxicity without requiring the use of lethal doses as a primary endpoint.", "pt-br": "O Procedimento de Dose Fixa é um método para a avaliação da toxicidade oral aguda em ratos, utilizando uma abordagem gradual para identificar doses que produzem sinais de toxicidade sem exigir o uso de doses letais como endpoint primário."}, "test_system": ["in_vivo"], "source_doc_id": 12, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [3], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 420: Acute Oral Toxicity - Fixed Dose Procedure. An in vivo test method using rats to assess acute oral toxicity through a stepwise dosing procedure to identify signs of toxicity while avoiding lethality.", "reduction_rationale": {"en-us": "The method uses a stepwise procedure with fixed doses, avoiding the use of lethal doses and significantly reducing the number of animals required compared to traditional LD50 tests.", "pt-br": "O método utiliza um procedimento gradual com doses fixas, evitando o uso de doses letais e reduzindo significativamente o número de animais necessários em comparação com os testes tradicionais de DL50."}, "refinement_rationale": {"en-us": "The method is designed to avoid severe toxic effects or mortality by using doses expected to produce signs of toxicity without death.", "pt-br": "O método foi projetado para evitar efeitos tóxicos graves ou mortalidade, utilizando doses esperadas para produzir sinais de toxicidade sem morte."}, "replacement_rationale": null}, {"id": 39, "name": {"en-us": "Test No. 492B: Reconstructed Human Cornea-like Epithelium (RhCE) Test Method for Eye Hazard Identification", "pt-br": "Teste Nº 492B: Método de Teste de Epitélio Corneano Humano Reconstruído (RhCE) para Identificação de Perigo Ocular"}, "slug": "oecd-tg492b-rhce-eye-hazard", "active": false, "ncit_id": null, "keywords": {"en-us": ["RhCE", "eye irritation", "serious eye damage", "MTT assay", "in vitro", "UN GHS"], "pt-br": ["RhCE", "irritação ocular", "dano ocular grave", "ensaio MTT", "in vitro", "GHS da ONU"]}, "oecd_ref": "TG 492B", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-07-31T16:27:52.624549+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro procedure using Reconstructed Human Cornea-like Epithelium (RhCE) to identify chemicals not requiring classification, requiring classification for eye irritation (Cat 2), or serious eye damage (Cat 1) according to UN GHS, based on the MTT cytotoxicity assay.", "pt-br": "Procedimento in vitro utilizando Epitélio Corneano Humano Reconstruído (RhCE) para identificar substâncias que não requerem classificação, que requerem classificação para irritação ocular (Cat 2) ou dano ocular grave (Cat 1) de acordo com o GHS da ONU, baseado no ensaio de citotoxicidade MTT."}, "test_system": ["in_vitro"], "source_doc_id": 9, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 492B: Reconstructed Human Cornea-like Epithelium (RhCE) Test Method for Eye Hazard Identification. An in vitro test system using RhCE tissue constructs and the MTT assay to identify ocular hazard potential according to UN GHS criteria.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Designed to provide an in vitro alternative for the identification of eye hazard categories without the need for animal testing.", "pt-br": "Projetado para fornecer uma alternativa in vitro para a identificação de categorias de perigo ocular sem a necessidade de testes em animais."}}, {"id": 12, "name": {"en-us": "OECD Test No. 442E: In Vitro Skin Sensitisation", "pt-br": "Teste OCDE No. 442E: Sensibilização Cutânea In Vitro"}, "slug": "oecd-tg442e-in-vitro-skin-sensitisation", "active": false, "ncit_id": null, "keywords": {"en-us": ["skin sensitisation", "dendritic cells", "h-CLAT", "U-SENS", "IL-8 Luc", "GARDskin", "AOP", "Adverse Outcome Pathway"], "pt-br": ["sensibilização cutânea", "células dendríticas", "h-CLAT", "U-SENS", "IL-8 Luc", "GARDskin", "AOP", "Via de Desfecho Adverso"]}, "oecd_ref": "TG 442E", "endpoints": [20], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "In vitro test guideline addressing the activation of dendritic cells within the skin sensitisation Adverse Outcome Pathway (AOP). Methods include h-CLAT, U-SENS, IL-8 Luc assay, and GARDskin, used for discriminating between skin sensitisers and non-sensitisers.", "pt-br": "Diretriz de teste in vitro que aborda a ativação de células dendríticas dentro da via de desfecho adverso (AOP) para sensibilização cutânea. Os métodos incluem h-CLAT, U-SENS, ensaio IL-8 Luc e GARDskin, usados para distinguir entre sensibilizantes e não sensibilizantes cutâneos."}, "test_system": ["in_vitro"], "source_doc_id": 28, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [1], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD Test No. 442E: In Vitro Skin Sensitisation. A guideline providing in vitro methods (h-CLAT, U-SENS, IL-8 Luc, GARDskin) to assess skin sensitisation by measuring dendritic cell activation within the AOP.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The guideline provides in vitro methods to address skin sensitisation without the use of animals by targeting key events in the AOP.", "pt-br": "A diretriz fornece métodos in vitro para abordar a sensibilização cutânea sem o uso de animais, visando eventos-chave na AOP."}}, {"id": 50, "name": {"en-us": "Test No. 495: Ros (Reactive Oxygen Species) Assay for Photoreactivity", "pt-br": "Teste nº 495: Ensaio de Especies Reativas de Oxigenio (ROS) para Fotorreatividade"}, "slug": "oecd-tg495-ros-assay-photoreactivity", "active": false, "ncit_id": null, "keywords": {"en-us": ["photoreactivity", "phototoxicity", "reactive oxygen species", "ROS", "chemical safety"], "pt-br": ["fotorreatividade", "fototoxicidade", "especies reativas de oxigenio", "ROS", "seguranca quimica"]}, "oecd_ref": "TG 495", "endpoints": [37], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-08T01:49:44.729591+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A test method to measure the phototoxicity of a chemical by detecting the generation of Reactive Oxygen Species (ROS) from irradiated chemicals under simulated sunlight.", "pt-br": "Um metodo de teste para medir a fototoxicidade de uma substancia quimica atraves da deteccao da geracao de Especies Reativas de Oxigenio (ROS) a partir de substancias irradiadas sob luz solar simulada."}, "test_system": ["in_chemico"], "source_doc_id": 43, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": null, "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "oecd-tg495-ros-assay-photoreactivity Test No. 495: Ros (Reactive Oxygen Species) Assay for Photoreactivity. A test method to measure the phototoxicity of a chemical by detecting the generation of Reactive Oxygen Species (ROS) from irradiated chemicals under simulated sunlight.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The ROS assay is an in chemico method that assesses phototoxicity without the use of animals.", "pt-br": "O ensaio de ROS e um metodo in chemico que avalia a fototoxicidade sem o uso de animais."}}, {"id": 20, "name": {"en-us": "Monocyte Activation Test (MAT)", "pt-br": "Teste de Ativação de Monócitos (MAT)"}, "slug": "farmacopeia-MG5.5.2.7.1-00-teste-de-ativacao-de-monocitos-mat", "active": false, "ncit_id": null, "keywords": {"en-us": ["MAT", "pyrogen", "endotoxin", "parenteral products", "cytokines"], "pt-br": ["MAT", "pirogênio", "endotoxina", "produtos parenterais", "citocinas"]}, "oecd_ref": null, "endpoints": [48], "source_db": "FARMACOPEIA_BR", "animal_use": "animal_derived_material", "created_at": "2026-06-12T00:36:18.616129+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "An in vitro method for the detection of bacterial endotoxins and non-endotoxin pyrogens (NEPs) in parenteral products, using human monocytes or monocytic cell lines to measure the release of pro-inflammatory cytokines.", "pt-br": "Método in vitro para a detecção de endotoxinas bacterianas e pirogênios não-endotoxina (NEPs) em produtos parenterais, utilizando monócitos humanos ou linhagens celulares monocíticas para medir a liberação de citocinas pró-inflamatórias."}, "test_system": ["in_vitro"], "source_doc_id": 1, "embedding_json": null, "application_ids": [3], "source_citation": "{\"pt-br\":\"5.5.2.7.1 TESTE DE ATIVAÇÃO DE MONÓCITOS.  Farmacopeia Brasileira, 7ª edição: volume I - versão RDC nº 940/2024. MG5.5.2.7.1-00.\"}", "routes_applicable": [7], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "Monocyte Activation Test (MAT) - An in vitro method for the detection of bacterial endotoxins and non-endotoxin pyrogens (NEPs) in parenteral products, serving as a replacement for the rabbit pyrogen test.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "Recommended in preference to the rabbit pyrogen test to reduce the use of animals.", "pt-br": "Recomenda-se a sua utilização, em detrimento do teste de pirogênios em coelhos visando à redução de uso de animais."}}, {"id": 49, "name": {"en-us": "In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage", "pt-br": "Método de teste macromolecular in vitro para identificar produtos químicos que induzem lesões oculares graves e produtos químicos que não requerem classificação para irritação ocular ou lesões oculares graves"}, "slug": "oecd-tg496-in-vitro-macromolecular-test-method", "active": false, "ncit_id": null, "keywords": {"en-us": ["macromolecular reagent", "corneal opacity", "protein denaturation", "eye hazard", "turbidity"], "pt-br": ["reagente macromolecular", "opacidade corneana", "desnaturação proteica", "perigo ocular", "turbidez"]}, "oecd_ref": "TG 496", "endpoints": [14, 15], "source_db": "OECD_TG", "animal_use": null, "created_at": "2026-08-08T01:42:42.018017+00:00", "updated_at": "2026-08-15T03:34:37.644052+00:00", "description": {"en-us": "A biochemical in vitro test method that uses a macromolecular reagent matrix mimicking the corneal structure. It identifies chemicals inducing serious eye damage and those not requiring classification by measuring protein denaturation and matrix turbidity via light scattering.", "pt-br": "Um método de teste bioquímico in vitro que utiliza uma matriz de reagente macromolecular que mimetiza a estrutura da córnea. Identifica produtos químicos que induzem lesões oculares graves e aqueles que não requerem classificação medindo a desnaturação proteica e a turbidez da matriz por meio de dispersão de luz."}, "test_system": ["in_vitro", "in_chemico"], "source_doc_id": 42, "embedding_json": null, "application_ids": [3], "source_citation": null, "routes_applicable": [4], "validation_doc_id": null, "validation_status": "validated", "text_for_embedding": "OECD TG 496: In vitro Macromolecular Test Method for Identifying Chemicals Inducing Serious Eye Damage and Chemicals Not Requiring Classification for Eye Irritation or Serious Eye Damage. A biochemical in vitro method measuring turbidity of a macromolecular matrix to assess ocular irritation potential.", "reduction_rationale": null, "refinement_rationale": null, "replacement_rationale": {"en-us": "The test method allows for the identification of serious eye damage and classification status in vitro, reducing the reliance on animal testing for eye irritation assessments.", "pt-br": "O método de teste permite a identificação de lesões oculares graves e status de classificação in vitro, reduzindo a dependência de testes em animais para avaliações de irritação ocular."}}]'::jsonb);
