INSERT INTO public."routes" ("slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "compatible_endpoints", "id") SELECT "slug", "name", "description", "sort_order", "active", "created_at", "updated_at", "compatible_endpoints", "id" FROM jsonb_populate_recordset(null::public."routes", '[{"id": 1, "name": {"en-us": "Cutaneous", "pt-br": "Cutânea"}, "slug": "cutaneous", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 1, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Application to or exposure of the external skin surface; excludes injection into the dermis.", "pt-br": "Aplicação ou exposição à superfície externa da pele; exclui injeção na derme."}, "compatible_endpoints": [3, 10, 11, 12, 17, 18, 20, 22, 23, 25, 26, 28, 29, 30]}, {"id": 2, "name": {"en-us": "Inhalation", "pt-br": "Inalação"}, "slug": "inhalation", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 2, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Exposure through the respiratory tract to gases, vapours, aerosols or particles.", "pt-br": "Exposição pelo trato respiratório a gases, vapores, aerossóis ou partículas."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 3, "name": {"en-us": "Oral", "pt-br": "Oral"}, "slug": "oral", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 3, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Entry through the mouth and gastrointestinal tract, including administration by gavage, diet or drinking water.", "pt-br": "Entrada pela boca e pelo trato gastrointestinal, incluindo administração por gavagem, dieta ou água de beber."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 4, "name": {"en-us": "Ocular", "pt-br": "Ocular"}, "slug": "ocular", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 4, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Direct application to or exposure of the eye or ocular surface.", "pt-br": "Aplicação direta ou exposição do olho ou da superfície ocular."}, "compatible_endpoints": [12, 14, 15]}, {"id": 5, "name": {"en-us": "Intranasal", "pt-br": "Intranasal"}, "slug": "intranasal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 5, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into the nasal cavity.", "pt-br": "Administração na cavidade nasal."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 6, "name": {"en-us": "Intratracheal", "pt-br": "Intratraqueal"}, "slug": "intratracheal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 6, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration directly into the trachea.", "pt-br": "Administração diretamente na traqueia."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 7, "name": {"en-us": "Intravenous", "pt-br": "Intravenosa"}, "slug": "intravenous", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 7, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into a vein.", "pt-br": "Administração em uma veia."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30, 48, 49, 50, 51]}, {"id": 8, "name": {"en-us": "Intra-arterial", "pt-br": "Intra-arterial"}, "slug": "intra-arterial", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 8, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into an artery.", "pt-br": "Administração em uma artéria."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 9, "name": {"en-us": "Intramuscular", "pt-br": "Intramuscular"}, "slug": "intramuscular", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 9, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into muscle tissue.", "pt-br": "Administração no tecido muscular."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30, 48, 49, 50, 51]}, {"id": 10, "name": {"en-us": "Subcutaneous", "pt-br": "Subcutânea"}, "slug": "subcutaneous", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 10, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into tissue beneath the skin.", "pt-br": "Administração no tecido localizado abaixo da pele."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30, 48, 49, 50, 51]}, {"id": 11, "name": {"en-us": "Intradermal", "pt-br": "Intradérmica"}, "slug": "intradermal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 11, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into the dermis.", "pt-br": "Administração na derme."}, "compatible_endpoints": [17, 18, 20, 22, 23, 25, 26, 28, 29, 30]}, {"id": 12, "name": {"en-us": "Intraperitoneal", "pt-br": "Intraperitoneal"}, "slug": "intraperitoneal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 12, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into the peritoneal cavity.", "pt-br": "Administração na cavidade peritoneal."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 13, "name": {"en-us": "Rectal", "pt-br": "Retal"}, "slug": "rectal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 13, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into or exposure through the rectum.", "pt-br": "Administração no reto ou exposição pela via retal."}, "compatible_endpoints": [17, 18, 22, 23, 25, 26, 28, 29, 30]}, {"id": 14, "name": {"en-us": "Vaginal", "pt-br": "Vaginal"}, "slug": "vaginal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 14, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Administration into or exposure through the vagina.", "pt-br": "Administração na vagina ou exposição pela via vaginal."}, "compatible_endpoints": [8, 17, 18, 20, 22, 23, 25, 26, 28, 29, 30]}, {"id": 15, "name": {"en-us": "Topical mucosal", "pt-br": "Tópica em mucosa"}, "slug": "topical-mucosal", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 15, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Local application to a mucosal surface not represented by a more specific route.", "pt-br": "Aplicação local em uma superfície mucosa não representada por uma via mais específica."}, "compatible_endpoints": [8, 17, 18, 20]}, {"id": 16, "name": {"en-us": "Implantation", "pt-br": "Implantação"}, "slug": "implantation", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 16, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Placement of a test material or device within tissue or a body cavity.", "pt-br": "Colocação de um material de teste ou dispositivo em um tecido ou cavidade corporal."}, "compatible_endpoints": [8, 17, 18, 20, 22, 23, 25, 26, 28, 29, 30]}, {"id": 17, "name": {"en-us": "Multiple routes", "pt-br": "Múltiplas vias"}, "slug": "multiple", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 17, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "Exposure or administration occurs through more than one route, but the individual routes are not recorded separately.", "pt-br": "A exposição ou administração ocorre por mais de uma via, mas as vias individuais não são registradas separadamente."}, "compatible_endpoints": []}, {"id": 18, "name": {"en-us": "Not applicable", "pt-br": "Não aplicável"}, "slug": "not-applicable", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 18, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "No organism-level exposure or administration route applies to the method or study.", "pt-br": "Nenhuma via de exposição ou administração em nível de organismo se aplica ao método ou estudo."}, "compatible_endpoints": []}, {"id": 19, "name": {"en-us": "Unspecified", "pt-br": "Não especificada"}, "slug": "unspecified", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 19, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "An exposure or administration route may exist, but it is not reported or cannot be determined.", "pt-br": "Pode existir uma via de exposição ou administração, mas ela não foi informada ou não pode ser determinada."}, "compatible_endpoints": []}, {"id": 20, "name": {"en-us": "Other", "pt-br": "Outra"}, "slug": "other", "active": true, "created_at": "2026-08-15T03:34:37.644052+00:00", "sort_order": 20, "updated_at": "2026-08-15T14:11:09.432085+00:00", "description": {"en-us": "A known exposure or administration route not represented by the controlled vocabulary.", "pt-br": "Uma via conhecida de exposição ou administração não representada pelo vocabulário controlado."}, "compatible_endpoints": []}, {"id": 21, "name": {"en-us": "Aquatic (waterborne)", "pt-br": "Aquática (na água)"}, "slug": "aquatic-waterborne", "active": true, "created_at": "2026-10-09T17:13:52.173984+00:00", "sort_order": 21, "updated_at": "2026-10-09T17:13:52.173984+00:00", "description": {"en-us": "Exposure of aquatic organisms to a test substance in test water.", "pt-br": "Exposição de organismos aquáticos a uma substância de ensaio na água do teste."}, "compatible_endpoints": [39]}]'::jsonb);
