ALTER TABLE ONLY users ADD CONSTRAINT "users_email_key" UNIQUE (email);
ALTER TABLE ONLY documents ADD CONSTRAINT "documents_categories_is_array" CHECK ((jsonb_typeof(categories) = 'array'::text));
ALTER TABLE ONLY documents ADD CONSTRAINT "documents_categories_not_empty" CHECK ((jsonb_array_length(categories) >= 1));
ALTER TABLE ONLY documents ADD CONSTRAINT "documents_categories_values_check" CHECK ((categories <@ '["method_protocol", "guideline", "regulation", "other"]'::jsonb));
ALTER TABLE ONLY methods ADD CONSTRAINT "methods_animal_use_check" CHECK (((animal_use IS NULL) OR (animal_use = ANY (ARRAY['none'::text, 'animal_derived_material'::text, 'slaughterhouse_byproduct'::text, 'animals_killed_for_tissue'::text, 'live_animals'::text, 'mixed_or_variable'::text]))));
ALTER TABLE ONLY methods ADD CONSTRAINT "methods_test_system_is_array" CHECK (((test_system IS NULL) OR (jsonb_typeof(test_system) = 'array'::text)));
ALTER TABLE ONLY methods ADD CONSTRAINT "methods_test_system_values_check" CHECK (((test_system IS NULL) OR (test_system <@ '["in_silico", "in_chemico", "in_vitro", "ex_vivo", "in_vivo", "hybrid", "unclear"]'::jsonb)));
ALTER TABLE ONLY methods ADD CONSTRAINT "methods_validation_status_check" CHECK ((validation_status = ANY (ARRAY['not_evaluated'::text, 'under_validation'::text, 'validated'::text, 'partially_validated'::text, 'not_validated'::text, 'unclear'::text])));
ALTER TABLE ONLY queries ADD CONSTRAINT "queries_confidence_check" CHECK ((confidence = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text])));
ALTER TABLE ONLY query_feedback ADD CONSTRAINT "query_feedback_rating_check" CHECK ((rating = ANY (ARRAY['relevant'::text, 'partial'::text, 'not_relevant'::text])));
ALTER TABLE ONLY regulations ADD CONSTRAINT "regulations_regulatory_status_check" CHECK (((regulatory_status IS NULL) OR (regulatory_status = ANY (ARRAY['not_approved'::text, 'approved'::text, 'recommended'::text, 'mandatory'::text]))));
ALTER TABLE ONLY suggestions ADD CONSTRAINT "suggestions_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'reviewed'::text, 'accepted'::text, 'rejected'::text])));
ALTER TABLE ONLY feedback ADD CONSTRAINT "feedback_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE ONLY endpoints ADD CONSTRAINT "fk_endpoints_parent" FOREIGN KEY (parent_id) REFERENCES endpoints(id) ON DELETE SET NULL;
ALTER TABLE ONLY methods ADD CONSTRAINT "fk_methods_source_doc" FOREIGN KEY (source_doc_id) REFERENCES documents(id) ON DELETE SET NULL;
ALTER TABLE ONLY methods ADD CONSTRAINT "fk_methods_validation_doc" FOREIGN KEY (validation_doc_id) REFERENCES documents(id) ON DELETE SET NULL;
ALTER TABLE ONLY regulations ADD CONSTRAINT "fk_regulations_regulatory_doc" FOREIGN KEY (regulatory_doc_id) REFERENCES documents(id) ON DELETE SET NULL;
ALTER TABLE ONLY magic_link_tokens ADD CONSTRAINT "magic_link_tokens_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;
ALTER TABLE ONLY queries ADD CONSTRAINT "queries_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE ONLY query_feedback ADD CONSTRAINT "query_feedback_method_id_fkey" FOREIGN KEY (method_id) REFERENCES methods(id) ON DELETE CASCADE;
ALTER TABLE ONLY query_feedback ADD CONSTRAINT "query_feedback_query_id_fkey" FOREIGN KEY (query_id) REFERENCES queries(id) ON DELETE CASCADE;
ALTER TABLE ONLY regulations ADD CONSTRAINT "regulations_method_id_fkey" FOREIGN KEY (method_id) REFERENCES methods(id) ON DELETE CASCADE;
ALTER TABLE ONLY suggestions ADD CONSTRAINT "suggestions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL;
CREATE INDEX idx_applications_active ON public.applications USING btree (active) WHERE (active = true);
CREATE INDEX idx_documents_categories ON public.documents USING gin (categories);
CREATE INDEX idx_documents_date ON public.documents USING btree (date);
CREATE INDEX idx_endpoints_active ON public.endpoints USING btree (active) WHERE (active = true);
CREATE INDEX idx_endpoints_parent ON public.endpoints USING btree (parent_id);
CREATE INDEX idx_feedback_created_at ON public.feedback USING btree (created_at DESC);
CREATE INDEX idx_feedback_user_id ON public.feedback USING btree (user_id);
CREATE INDEX idx_magic_link_expires ON public.magic_link_tokens USING btree (expires_at) WHERE (used_at IS NULL);
CREATE INDEX idx_magic_link_token_hash ON public.magic_link_tokens USING btree (token_hash);
CREATE INDEX idx_methods_active ON public.methods USING btree (active);
CREATE INDEX idx_methods_application_ids ON public.methods USING gin (application_ids);
CREATE INDEX idx_methods_endpoints ON public.methods USING gin (endpoints);
CREATE INDEX idx_methods_routes_applicable ON public.methods USING gin (routes_applicable);
CREATE INDEX idx_methods_source_doc ON public.methods USING btree (source_doc_id);
CREATE INDEX idx_methods_test_system ON public.methods USING gin (test_system);
CREATE INDEX idx_methods_validation_doc ON public.methods USING btree (validation_doc_id);
CREATE INDEX idx_mvc_method ON public.regulations USING btree (method_id);
CREATE INDEX idx_mvc_regulatory_doc ON public.regulations USING btree (regulatory_doc_id);
CREATE INDEX idx_queries_created_at ON public.queries USING btree (created_at DESC);
CREATE INDEX idx_queries_user_id ON public.queries USING btree (user_id);
CREATE INDEX idx_query_feedback_method_id ON public.query_feedback USING btree (method_id);
CREATE INDEX idx_query_feedback_query_id ON public.query_feedback USING btree (query_id);
CREATE INDEX idx_query_feedback_rating ON public.query_feedback USING btree (rating);
CREATE INDEX idx_regulations_jurisdiction ON public.regulations USING btree (jurisdiction);
CREATE INDEX idx_routes_active ON public.routes USING btree (active) WHERE (active = true);
CREATE INDEX idx_suggestions_status ON public.suggestions USING btree (status) WHERE (status = 'pending'::text);
CREATE INDEX pubmed_cluster_idx ON public.pubmed_abstracts USING btree (cluster);
CREATE INDEX pubmed_mesh_idx ON public.pubmed_abstracts USING gin (mesh_terms);
CREATE INDEX pubmed_pub_year_idx ON public.pubmed_abstracts USING btree (pub_year DESC NULLS LAST);
CREATE UNIQUE INDEX applications_id_key ON public.applications USING btree (id);
CREATE UNIQUE INDEX endpoints_id_key ON public.endpoints USING btree (id);
CREATE UNIQUE INDEX routes_id_key ON public.routes USING btree (id);
CREATE TRIGGER endpoints_updated_at BEFORE UPDATE ON public.endpoints FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER routes_updated_at BEFORE UPDATE ON public.routes FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER applications_updated_at BEFORE UPDATE ON public.applications FOR EACH ROW EXECUTE FUNCTION set_updated_at();

COMMIT;
